import React, { useState, useEffect, useContext } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Container, Spinner, Alert, Button } from 'react-bootstrap';
import { isDarkModeEnabled } from '../settings';
import { PolyglotContext } from '../components/PolyglotProvider';
import { createCheckoutSession } from '../api';
import { loadStripe } from '@stripe/stripe-js';
import { Elements } from '@stripe/react-stripe-js';
import StripePaymentForm from '../components/StripePaymentForm';

// Initialize Stripe outside of component to avoid recreation on every render
const stripePromise = loadStripe(process.env.REACT_APP_STRIPE_PUBLISHABLE_KEY);

const Payment = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { polyglot } = useContext(PolyglotContext);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [clientSecret, setClientSecret] = useState(null);
  const darkMode = isDarkModeEnabled();

  const planKey = location.state?.plan;
  const planConfig = location.state?.planConfig;

  useEffect(() => {
    // Scroll to top on mount
    window.scrollTo({ top: 0, behavior: 'auto' });

    if (!planKey) {
      navigate('/paywall');
      return;
    }

    const initializeCheckout = async () => {
      try {
        const token = localStorage.getItem('jerryToken');
        // Use the planKey (e.g., 'pro', 'elite') as the plan_name for the backend
        const response = await createCheckoutSession(token, planKey);

        if (response.client_secret) {
          // New embedded flow
          setClientSecret(response.client_secret);
          setLoading(false);
        } else if (response.checkout_url) {
          // Legacy Redirect flow (fallback)
          window.location.href = response.checkout_url;
        } else {
          setError(polyglot.t("payment.errorStripeInit"));
          setLoading(false);
        }
      } catch (err) {
        console.error("Error creating checkout session:", err);
        setError(polyglot.t("payment.errorStripeConnect"));
        setLoading(false);
      }
    };

    initializeCheckout();
  }, [planKey, navigate]);

  if (error) {
    return (
      <Container className="d-flex align-items-center justify-content-center" style={{ minHeight: '80vh' }}>
        <div className="text-center p-5" style={{
          background: darkMode ? '#18213a' : '#fff',
          borderRadius: '24px',
          border: darkMode ? '1px solid #22304a' : '1px solid #eef2f7',
          boxShadow: darkMode ? '0 20px 40px rgba(0,0,0,0.4)' : '0 20px 40px rgba(0,0,0,0.05)',
          maxWidth: '500px',
          width: '100%'
        }}>
          <h2 className="mb-4" style={{ fontWeight: 700 }}>{polyglot.t('payment.oops')}</h2>
          <Alert variant="danger" className="mb-4" style={{ borderRadius: '12px' }}>
            {error}
          </Alert>
          <Button
            variant="primary"
            onClick={() => navigate('/paywall')}
            style={{
              borderRadius: '8px',
              padding: '0.75rem 2rem',
              fontWeight: 600,
              width: '100%'
            }}
          >
            {polyglot.t('payment.actions.backToPlans')}
          </Button>
        </div>
      </Container>
    );
  }

  if (loading || !clientSecret) {
    // Consistent loading state with the rest of the app
    return (
      <div style={{
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        height: '80vh',
        background: darkMode ? '#101624' : '#fff',
        color: darkMode ? '#e0e6f0' : '#222'
      }}>
        <div className="d-flex justify-content-center mb-4">
          <Spinner
            animation="border"
            variant="primary"
            style={{ width: '4rem', height: '4rem', borderWidth: '0.25em' }}
          />
        </div>
        <h2 style={{ fontWeight: 700, marginBottom: '1rem' }}>
          {polyglot.t('payment.redirecting')}
        </h2>
        <p style={{ color: darkMode ? '#8fa3c8' : '#666', fontSize: '1.1rem', maxWidth: '400px', textAlign: 'center' }}>
          {polyglot.t('payment.security.description')}
        </p>
        <div className="mt-4">
          <Spinner animation="grow" size="sm" variant="primary" className="me-2" />
          <Spinner animation="grow" size="sm" variant="primary" className="me-2" />
          <Spinner animation="grow" size="sm" variant="primary" />
        </div>
      </div>
    );
  }

  // Stripe Elements options
  const elementsOptions = {
    clientSecret,
    appearance: {
      theme: darkMode ? 'night' : 'stripe',
      variables: {
        colorPrimary: '#007bff',
      },
    },
  };

  return (
    <Container className="py-5" style={{ minHeight: '80vh' }}>
      <div className="mx-auto" style={{ maxWidth: '600px' }}>
        <div className="text-center mb-5">
          <h2 style={{ fontWeight: 700 }}>{polyglot.t('payment.title')}</h2>
          <p style={{ color: darkMode ? '#8fa3c8' : '#666' }}>{polyglot.t('payment.subtitle')}</p>
        </div>

        <div style={{
          background: darkMode ? '#18213a' : '#fff',
          padding: '2rem',
          borderRadius: '16px',
          border: darkMode ? '1px solid #22304a' : '1px solid #eef2f7',
          boxShadow: darkMode ? '0 10px 30px rgba(0,0,0,0.2)' : '0 10px 30px rgba(0,0,0,0.03)'
        }}>
          <Elements stripe={stripePromise} options={elementsOptions}>
            <StripePaymentForm
              planKey={planKey}
              planPrice={planConfig?.price || ''}
              polyglot={polyglot}
              darkMode={darkMode}
            />
          </Elements>
        </div>

        <div className="mt-4 text-center">
          <p style={{ fontSize: '0.9rem', color: darkMode ? '#5a6b8a' : '#999' }}>
            <i className="bi bi-shield-lock-fill me-2"></i>
            {polyglot.t('payment.security.description')}
          </p>
        </div>
      </div>
    </Container>
  );
};

export default Payment;