import React, { useEffect, useState } from 'react';
import { isDarkModeEnabled } from '../settings';
import { Capacitor } from '@capacitor/core';

const Footer = () => {
  // Force re-render on dark mode toggle
  const [mode, setMode] = useState(isDarkModeEnabled());
  const isMobile = Capacitor.isNativePlatform();

  useEffect(() => {
    const interval = setInterval(() => {
      setMode(isDarkModeEnabled());
    }, 300);
    return () => clearInterval(interval);
  }, []);



  const darkMode = mode;
  const darkBg = '#0b101a'; // even darker for footer
  const darkText = '#e0e6f0';

  return (
    <footer
      className="footer text-center py-2"
      style={darkMode ? {
        backgroundColor: darkBg,
        color: darkText,
        fontSize: '0.9rem',
        paddingBottom: isMobile ? 'var(--safe-area-bottom)' : '0.5rem',
      } : {
        backgroundColor: '#e0d7d4',
        color: '#222', 
        fontSize: '0.9rem',
        paddingBottom: isMobile ? 'var(--safe-area-bottom)' : '0.5rem',
      }}
    >
      <p style={{ margin: 0 }}>
        &copy; {new Date().getFullYear()} Jerry - v{process.env.REACT_APP_VERSION}
      </p>
    </footer>
  );
};

export default Footer;
