import { getProfile as apiGetProfile } from './api';
import { getUserData } from './jerryTokenUtil';

// Utility to get a sessionStorage key for a user
const getProfileKey = () => {
  const userData = getUserData();
  if (!userData) return null;
  return `${userData.hashedEmail}.profile`;
};

/**
 * Get the user profile from sessionStorage if available, otherwise fetch from API and cache it.
 * @param {string} token - The user's auth token
 * @returns {Promise<Object>} The user profile object
 */
export const getProfile = async (token) => {
  const profileKey = getProfileKey();
  if (!profileKey) throw new Error('No user data');

  // Try to get from sessionStorage
  const cached = sessionStorage.getItem(profileKey);
  if (cached) {
    try {
      return JSON.parse(cached);
    } catch (e) {
      // If parsing fails, fall through to fetch
    }
  }

  // Fetch from API and cache
  const profile = await apiGetProfile(token);
  sessionStorage.setItem(profileKey, JSON.stringify(profile));
  return profile;
};

/**
 * Get the plans configuration from sessionStorage if available, otherwise fetch from plans.json and cache it.
 * @param {string} basepath - The base path for the application
 * @returns {Promise<Object>} The plans configuration object
 */
export const getPlans = async (basepath) => {
  const plansKey = 'plans.config';

  // Try to get from sessionStorage
  const cached = sessionStorage.getItem(plansKey);
  if (cached) {
    try {
      return JSON.parse(cached);
    } catch (e) {
      // If parsing fails, fall through to fetch
    }
  }

  // Fetch from plans.json and cache
  try {
    const res = await fetch(`${basepath}/plans.json`);
    if (!res.ok) {
      throw new Error(`Failed to fetch plans: ${res.status}`);
    }
    const plans = await res.json();
    sessionStorage.setItem(plansKey, JSON.stringify(plans));
    return plans;
  } catch (error) {
    console.error('Error fetching plans:', error);
    throw error;
  }
};

/**
 * Check if a user's plan allows a specific action based on their current plan and the action type.
 * @param {Object} userProfile - The user's profile object containing plan_name
 * @param {Object} plans - The plans configuration object
 * @param {string} actionType - The type of action to check ('timeframes', 'maxTrackedCryptos', 'maxNotifications')
 * @param {any} actionValue - The value to check against the plan limit
 * @returns {boolean} True if the action is allowed, false otherwise
 */
export const checkPlanLimit = (userProfile, plans, actionType, actionValue) => {
  if (!userProfile || !userProfile.plan_name || !plans) {
    return false;
  }

  const userPlan = plans[userProfile.plan_name.toLowerCase()];
  if (!userPlan) {
    return false;
  }

  switch (actionType) {
    case 'timeframes':
      return userPlan.timeframes.includes(actionValue);
    case 'maxTrackedCryptos':
      return actionValue <= userPlan.maxTrackedCryptos;
    case 'maxNotifications':
      return actionValue <= userPlan.maxNotifications;
    case 'refreshInterval':
      return actionValue >= userPlan.refreshInternvalSec;
    default:
      return false;
  }
};

// You can add more cache helpers here for other attributes as needed

/**
 * Clear user-specific session storage caches.
 * Useful after a plan upgrade to force fresh data fetching.
 */
export const clearSessionCache = () => {
  const userData = getUserData();
  if (userData && userData.hashedEmail) {
    const hashedEmail = userData.hashedEmail;
    sessionStorage.removeItem(`${hashedEmail}.profile`);
    sessionStorage.removeItem(`${hashedEmail}.timeframes`);
    sessionStorage.removeItem(`${hashedEmail}.markets`);
  }
  // Also clear the legacy placeholder
  localStorage.removeItem('userProfile');
};
