const apiRequest = async ({ token = null, endpoint, method = 'GET', payload = null }) => {

  console.log(`API Request - ${method} ${endpoint} -> ${JSON.stringify(payload)}`);

  const options = {
    method,
    headers: {
      ...(token && { Authorization: `Bearer ${token}` }),
      ...(method !== 'GET' && { 'Content-Type': 'application/json' }),
      'ngrok-skip-browser-warning': 'true',
    },
    ...(payload && { body: JSON.stringify(payload) }),
  };

  const baseUrl = process.env.REACT_APP_API_URL ? `${process.env.REACT_APP_API_URL}/` : '/';
  const response = await fetch(`${baseUrl}${endpoint}`, options);

  if (response.status === 401) {
    const auth0Token = localStorage.getItem('auth0Token');

    try {
      const jerryToken = await createJerryToken(auth0Token);
      localStorage.setItem('jerryToken', jerryToken);

      // Retry the API request with the refreshed token
      return await apiRequest({ token: jerryToken, endpoint, method, payload });
    } catch (error) {
      console.error("Could not refresh token", error);
      document.dispatchEvent(new CustomEvent('auth0TokenExpired'));
      return;
    }
  }

  if (!response.ok) {
    let errorMessage = 'An error occurred';
    try {
      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        const errorRes = await response.json();
        errorMessage = errorRes.error || errorMessage;
      } else {
        errorMessage = await response.text();
      }
    } catch (e) {
      console.error("Error parsing error response", e);
    }
    throw new Error(errorMessage);
  }

  return response.json();
};

