/**
 * Create a subscription session.
 * For the new embedded flow, the backend returns a client_secret from the 
 * latest invoice's payment intent.
 * @param {string} token - The user's auth token
 * @param {string} planName - The name of the plan (e.g., 'pro', 'elite')
 * @returns {Promise<Object>} The response containing client_secret or checkout_url
 */
export const createCheckoutSession = async (token, planName) => {
  return apiRequest({
    token,
    endpoint: 'payment/subscription',
    method: 'POST',
    payload: { plan_name: planName },
  });
};

