import React, { useState, useEffect } from 'react';
import { Card, Row, Col } from 'react-bootstrap';
import { fetchSignals } from '../api';
import CryptoLogo from './CryptoLogo';
import { useNavigate } from 'react-router-dom';
import { getUserData } from '../jerryTokenUtil';
import SignalPill from './SignalPill';
import { isDarkModeEnabled } from '../settings';
import './SignalData.css';

// Helper: dominant signal for a group (buy > sell > hold)
const getDominantSignal = (signals) => {
    if (signals.some(s => s.signal === 'buy')) return 'buy';
    if (signals.some(s => s.signal === 'sell')) return 'sell';
    return 'hold';
};

// Helper: get base currency from symbol (e.g. BTCUSDT -> BTC)
const getBaseCurrency = (symbol) => {
    return symbol.replace('USDT', '').replace('USDC', '');
};

// Helper: group signals by symbol
const groupBySymbol = (signals) => {
    const groups = {};
    for (const s of signals) {
        if (!groups[s.symbol]) groups[s.symbol] = [];
        groups[s.symbol].push(s);
    }
    // Sort entries: buy > sell > hold, then alphabetically
    const order = { buy: 1, sell: 2, hold: 3 };
    return Object.entries(groups).sort(([, a], [, b]) => {
        const da = getDominantSignal(a);
        const db = getDominantSignal(b);
        if (order[da] !== order[db]) return order[da] - order[db];
        return a[0].symbol.localeCompare(b[0].symbol);
    });
};

// Mini badge for timeframe + market inside a group card
const SubSignalBadge = ({ signal, polyglot, darkMode, onClick }) => {
    const isBuy = signal.signal === 'buy';
    const isSell = signal.signal === 'sell';

    const borderColor = isBuy
        ? 'rgba(40, 167, 69, 0.5)'
        : isSell
            ? 'rgba(231, 76, 60, 0.5)'
            : darkMode ? 'rgba(44, 62, 80, 0.5)' : 'rgba(108,117,125,0.3)';

    const accentColor = isBuy
        ? (darkMode ? '#4fc3a1' : '#047857')
        : isSell
            ? (darkMode ? '#e57373' : '#b91c1c')
            : (darkMode ? '#8fa3c8' : '#475569');

    return (
        <div
            onClick={(e) => { e.stopPropagation(); onClick(signal); }}
            style={{
                display: 'flex',
                alignItems: 'center',
                gap: '8px',
                padding: '8px 12px',
                borderRadius: '10px',
                border: `1.5px solid ${borderColor}`,
                background: darkMode ? '#1a2540' : '#ffffff',
                cursor: 'pointer',
                transition: 'transform 0.15s ease, box-shadow 0.15s ease',
                flex: '1 1 140px',
                minWidth: '130px',
            }}
            onMouseEnter={(e) => {
                e.currentTarget.style.transform = 'translateY(-2px)';
                e.currentTarget.style.boxShadow = `0 4px 12px ${borderColor}`;
            }}
            onMouseLeave={(e) => {
                e.currentTarget.style.transform = 'translateY(0)';
                e.currentTarget.style.boxShadow = 'none';
            }}
        >
            {/* Timeframe bubble */}
            <span style={{
                background: darkMode ? '#22304a' : 'rgba(110,110,110,0.85)',
                color: '#fff',
                borderRadius: '50%',
                width: '28px',
                height: '28px',
                minWidth: '28px',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '0.6rem',
                fontWeight: 700,
                flexShrink: 0,
            }}>
                {signal.timeframe}
            </span>

            <div style={{ display: 'flex', flexDirection: 'column', gap: '2px', minWidth: 0 }}>
                <span style={{
                    fontSize: '0.7rem',
                    fontWeight: 600,
                    color: darkMode ? '#8fa3c8' : '#64748b',
                    textTransform: 'uppercase',
                    letterSpacing: '0.4px',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                }}>
                    {polyglot.t(`markets.${signal.market}`)}
                </span>
                <span style={{
                    fontSize: '0.8rem',
                    fontWeight: 700,
                    color: accentColor,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                }}>
                    {polyglot.t(`signal.value.${signal.signal}`)}
                </span>
            </div>

            {/* Arrow */}
            <span style={{
                marginLeft: 'auto',
                color: darkMode ? '#8fa3c8' : '#94a3b8',
                fontSize: '0.75rem',
                flexShrink: 0,
            }}>›</span>
        </div>
    );
};

// Group card: shows a crypto with all its signals collapsed/expanded
const CryptoGroupCard = ({ symbol, signals, polyglot, darkMode, onSignalClick }) => {
    const [expanded, setExpanded] = useState(false);
    const dominant = getDominantSignal(signals);
    const isBuy = dominant === 'buy';
    const isSell = dominant === 'sell';
    const baseCurrency = getBaseCurrency(symbol);

    const borderColor = isBuy
        ? 'rgba(40, 167, 69, 0.45)'
        : isSell
            ? 'rgba(231, 76, 60, 0.45)'
            : darkMode ? 'rgba(44, 62, 80, 0.5)' : 'rgba(108,117,125,0.25)';

    const accentColor = isBuy
        ? (darkMode ? '#4fc3a1' : '#16a34a')
        : isSell
            ? (darkMode ? '#e57373' : '#dc2626')
            : (darkMode ? '#8fa3c8' : '#64748b');

    // Collect unique timeframes and markets as summary tags
    const timeframes = [...new Set(signals.map(s => s.timeframe))];
    const markets = [...new Set(signals.map(s => s.market))];

    return (
        <div
            style={{
                borderRadius: '16px',
                border: `2px solid ${borderColor}`,
                background: darkMode ? '#18213a' : '#ffffff',
                boxShadow: expanded
                    ? `0 8px 24px ${borderColor}`
                    : '0 2px 8px rgba(0,0,0,0.06)',
                transition: 'box-shadow 0.25s ease, border-color 0.25s ease',
                overflow: 'hidden',
            }}
        >
            {/* Header: clickable to toggle */}
            <div
                onClick={() => setExpanded(prev => !prev)}
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '14px',
                    padding: '16px 18px',
                    cursor: 'pointer',
                    background: 'transparent',
                    userSelect: 'none',
                }}
                onMouseEnter={(e) => { e.currentTarget.style.background = darkMode ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)'; }}
                onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; }}
            >
                {/* Logo */}
                <div style={{ width: '44px', height: '44px', flexShrink: 0 }}>
                    <CryptoLogo
                        cryptoPairName={symbol}
                        customStyle={{ width: '100%', height: '100%', objectFit: 'contain' }}
                    />
                </div>

                {/* Name + summary tags */}
                <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{
                        fontSize: '1rem',
                        fontWeight: 700,
                        color: darkMode ? '#e0e6f0' : '#1e293b',
                        letterSpacing: '0.3px',
                        marginBottom: '4px',
                    }}>
                        {baseCurrency}
                        <span style={{ fontSize: '0.75rem', fontWeight: 500, color: darkMode ? '#8fa3c8' : '#64748b', marginLeft: '6px' }}>
                            {polyglot.t(`cryptoPairs.${symbol}`) !== `cryptoPairs.${symbol}` ? polyglot.t(`cryptoPairs.${symbol}`) : ''}
                        </span>
                    </div>

                    {/* Summary: timeframes + markets */}
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '4px', alignItems: 'center' }}>
                        {timeframes.map(tf => (
                            <span key={tf} style={{
                                fontSize: '0.6rem',
                                fontWeight: 700,
                                background: darkMode ? '#22304a' : 'rgba(100,100,100,0.12)',
                                color: darkMode ? '#a0b4d0' : '#475569',
                                borderRadius: '6px',
                                padding: '2px 6px',
                                textTransform: 'uppercase',
                                letterSpacing: '0.3px',
                            }}>{tf}</span>
                        ))}
                        {markets.map(m => (
                            <span key={m} style={{
                                fontSize: '0.6rem',
                                fontWeight: 600,
                                background: m === 'USD_M_FUTURES'
                                    ? (darkMode ? 'rgba(99,102,241,0.2)' : 'rgba(99,102,241,0.1)')
                                    : (darkMode ? 'rgba(16,185,129,0.15)' : 'rgba(16,185,129,0.1)'),
                                color: m === 'USD_M_FUTURES'
                                    ? (darkMode ? '#818cf8' : '#4f46e5')
                                    : (darkMode ? '#34d399' : '#059669'),
                                borderRadius: '6px',
                                padding: '2px 6px',
                                textTransform: 'uppercase',
                                letterSpacing: '0.3px',
                            }}>
                                {m === 'USD_M_FUTURES' ? 'Futures' : 'Spot'}
                            </span>
                        ))}
                    </div>
                </div>

                {/* Right side: count badge + dominant signal + chevron */}
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px', flexShrink: 0 }}>
                    <span style={{
                        background: darkMode ? '#22304a' : 'rgba(0,0,0,0.06)',
                        color: darkMode ? '#a0b4d0' : '#64748b',
                        borderRadius: '20px',
                        padding: '2px 10px',
                        fontSize: '0.75rem',
                        fontWeight: 600,
                    }}>
                        {signals.length}
                    </span>
                    <span style={{
                        fontSize: '0.75rem',
                        fontWeight: 700,
                        color: accentColor,
                        textTransform: 'uppercase',
                        letterSpacing: '0.5px',
                    }}>
                        {polyglot.t(`signal.value.${dominant}`)}
                    </span>
                    <span style={{
                        color: darkMode ? '#8fa3c8' : '#94a3b8',
                        fontSize: '1.1rem',
                        lineHeight: 1,
                        transition: 'transform 0.25s ease',
                        transform: expanded ? 'rotate(90deg)' : 'rotate(0deg)',
                        display: 'inline-block',
                    }}>›</span>
                </div>
            </div>

            {/* Expandable body */}
            <div style={{
                maxHeight: expanded ? '1000px' : '0px',
                overflow: 'hidden',
                transition: 'max-height 0.35s cubic-bezier(0.4, 0, 0.2, 1)',
            }}>
                <div style={{
                    padding: '0 16px 16px 16px',
                    borderTop: `1px solid ${darkMode ? 'rgba(44,62,80,0.5)' : 'rgba(0,0,0,0.06)'}`,
                    paddingTop: '14px',
                }}>
                    <div style={{
                        display: 'flex',
                        flexWrap: 'wrap',
                        gap: '8px',
                    }}>
                        {signals.map((signal, idx) => (
                            <SubSignalBadge
                                key={idx}
                                signal={signal}
                                polyglot={polyglot}
                                darkMode={darkMode}
                                onClick={onSignalClick}
                            />
                        ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

// ─── Main Component ───────────────────────────────────────────────────────────

const SignalData = ({ onDataLoaded, polyglot, refreshSignal, triggerRefresh, filters, hideActionsOnDesktop = false }) => {
    const [allSignals, setAllSignals] = useState([]);
    const [filteredSignals, setFilteredSignals] = useState([]);
    const [dataLoadedTs, setDataLoadedTs] = useState(null);
    const [loading, setLoading] = useState(true);
    const navigate = useNavigate();
    const userData = getUserData();
    const darkMode = isDarkModeEnabled();

    const signalDataKey = userData ? `${userData.hashedEmail}.signalData` : null;
    const signalDataUpdatedAtKey = userData ? `${userData.hashedEmail}.signalDataUpdatedAt` : null;

    const loadSignals = async (isRefresh = false) => {
        try {
            if (!isRefresh) setLoading(true);

            let signals;
            if (signalDataKey && signalDataUpdatedAtKey && !isRefresh) {
                const storedData = sessionStorage.getItem(signalDataKey);
                const signalDataUpdatedAt = sessionStorage.getItem(signalDataUpdatedAtKey);
                if (storedData && signalDataUpdatedAt) {
                    signals = JSON.parse(storedData);
                    setDataLoadedTs(signalDataUpdatedAt);
                    onDataLoaded(signalDataUpdatedAt);
                }
            }

            if (!signals) {
                const jerryToken = localStorage.getItem('jerryToken');
                signals = await fetchSignals(jerryToken);
                const timestamp = new Date().toLocaleString();
                setDataLoadedTs(timestamp);

                if (signalDataKey && signalDataUpdatedAtKey) {
                    sessionStorage.setItem(signalDataKey, JSON.stringify(signals));
                    sessionStorage.setItem(signalDataUpdatedAtKey, timestamp);
                }
                if (onDataLoaded) onDataLoaded(timestamp);
            }

            setAllSignals(signals);
        } catch (err) {
            console.error('Failed to load signals:', err);
            if (onDataLoaded) onDataLoaded(null);
        } finally {
            setLoading(false);
        }
    };

    const handleCardClick = (signal) => {
        navigate('/details', { state: { signal, lastUpdatedAt: dataLoadedTs } });
    };

    const handleAddClick = () => navigate('/add-crypto');

    useEffect(() => { loadSignals(); }, []);

    useEffect(() => {
        if (!allSignals || allSignals.length === 0) { setFilteredSignals([]); return; }
        if (!filters || (!filters.market && !filters.signal && !filters.reason)) {
            setFilteredSignals(allSignals); return;
        }
        setFilteredSignals(
            allSignals.filter(s => {
                if (filters.market && s.market !== filters.market) return false;
                if (filters.signal && s.signal !== filters.signal) return false;
                if (filters.reason && s.signalReason !== filters.reason) return false;
                return true;
            })
        );
    }, [allSignals, filters]);

    useEffect(() => {
        if (refreshSignal) loadSignals(true);
    }, [refreshSignal]);

    const groupedSignals = groupBySymbol(filteredSignals);

    return (
        <section className={darkMode ? 'signal-section-dark' : 'signal-section'}>
            {/* Add / Refresh action row */}
            <Row xs={1} sm={2} md={2} lg={2} xl={3} className="g-4">
                {/* Desktop Version */}
                {!hideActionsOnDesktop && (
                    <Col className="d-none d-md-block">
                        <div className="signal-add-container" style={{ gap: '12px', display: 'flex', flexDirection: 'column', height: '100%', justifyContent: 'center', alignItems: 'stretch' }}>
                            <div
                                className="shadow-sm"
                                onClick={() => triggerRefresh()}
                                style={{
                                    height: '48px', borderRadius: '12px', display: 'flex', justifyContent: 'center',
                                    alignItems: 'center', gap: '8px', cursor: 'pointer',
                                    background: darkMode ? '#1e293b' : '#f1f5f9',
                                    color: darkMode ? '#cbd5e1' : '#475569',
                                    border: darkMode ? '1px solid #334155' : '1px solid #cbd5e1',
                                    transition: 'transform 0.2s ease, opacity 0.2s ease',
                                }}
                                onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-2px)'; }}
                                onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0)'; }}
                            >
                                <span style={{ fontSize: '1.2rem', fontWeight: 600 }}>↻</span>
                                <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>{polyglot.t('label.refresh')}</span>
                            </div>
                            <div
                                className="shadow-sm"
                                onClick={handleAddClick}
                                style={{
                                    height: '48px', borderRadius: '12px', display: 'flex', justifyContent: 'center',
                                    alignItems: 'center', gap: '4px', cursor: 'pointer',
                                    background: darkMode ? '#3b82f6' : '#2563eb',
                                    color: '#ffffff', border: 'none',
                                    transition: 'transform 0.2s ease, opacity 0.2s ease',
                                }}
                                onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-2px)'; }}
                                onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0)'; }}
                            >
                                <span style={{ fontSize: '1.4rem', fontWeight: 500, lineHeight: 1 }}>＋</span>
                                <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>{polyglot.t('signal.addCrypto').replace('+', '').trim()}</span>
                            </div>
                        </div>
                    </Col>
                )}

                {/* Mobile Version */}
                <Col xs={12} className="d-flex d-md-none p-0">
                    <Row className="g-2 justify-content-center mb-4 mt-1" style={{ width: '100%', margin: '0' }}>
                        <Col xs={6}>
                            <div
                                className="shadow-sm d-flex justify-content-center align-items-center gap-2"
                                onClick={() => triggerRefresh()}
                                style={{
                                    height: '48px', borderRadius: '12px', width: '100%', cursor: 'pointer',
                                    background: darkMode ? '#1e293b' : '#f1f5f9',
                                    color: darkMode ? '#cbd5e1' : '#475569',
                                    border: darkMode ? '1px solid #334155' : '1px solid #cbd5e1',
                                    transition: 'all 0.2s ease',
                                }}
                            >
                                <span style={{ fontSize: '1.2rem', fontWeight: 600 }}>↻</span>
                                <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>{polyglot.t('label.refresh')}</span>
                            </div>
                        </Col>
                        <Col xs={6}>
                            <div
                                className="shadow-sm d-flex justify-content-center align-items-center gap-1"
                                onClick={handleAddClick}
                                style={{
                                    height: '48px', borderRadius: '12px', width: '100%', cursor: 'pointer',
                                    background: darkMode ? '#3b82f6' : '#2563eb',
                                    color: '#ffffff', border: 'none',
                                    transition: 'all 0.2s ease',
                                }}
                            >
                                <span style={{ fontSize: '1.4rem', fontWeight: 500, lineHeight: 1 }}>＋</span>
                                <span style={{ fontSize: '0.9rem', fontWeight: 600 }}>{polyglot.t('signal.addCrypto').replace('+', '').trim()}</span>
                            </div>
                        </Col>
                    </Row>
                </Col>
            </Row>

            {/* Grouped crypto cards */}
            <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '8px' }}>
                {groupedSignals.map(([symbol, signals]) => (
                    <CryptoGroupCard
                        key={symbol}
                        symbol={symbol}
                        signals={signals}
                        polyglot={polyglot}
                        darkMode={darkMode}
                        onSignalClick={handleCardClick}
                    />
                ))}
            </div>

            {/* Empty state */}
            {!loading && (!filteredSignals || filteredSignals.length === 0) && (
                <div className="w-100 d-flex justify-content-center mt-4" style={{ padding: '0 1rem' }}>
                    <Card
                        className={`shadow-sm text-center${darkMode ? ' signal-card-dark' : ''}`}
                        style={{
                            maxWidth: '450px',
                            border: darkMode ? '2px dashed rgba(44, 62, 80, 0.6)' : '2px dashed #cbd5e1',
                            background: darkMode ? '#18213a' : '#f8fafc',
                            padding: '40px 20px',
                            borderRadius: '16px',
                            width: '100%'
                        }}
                    >
                        <Card.Body>
                            <div style={{ fontSize: '3rem', marginBottom: '16px' }}>📡</div>
                            <h5 style={{ fontWeight: 700, color: darkMode ? '#ffffff' : '#1e293b' }}>
                                {polyglot.t('signal.noSignalsTitle')}
                            </h5>
                            <p style={{ color: darkMode ? '#8fa3c8' : '#64748b', fontSize: '0.9rem', marginBottom: '24px' }}>
                                {polyglot.t('signal.noSignalsDescription')}
                            </p>
                            <button
                                onClick={handleAddClick}
                                style={{
                                    background: darkMode ? '#3b82f6' : '#2563eb',
                                    color: '#ffffff', border: 'none', borderRadius: '8px',
                                    padding: '10px 24px', fontWeight: 600, cursor: 'pointer',
                                    boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                                    transition: 'background 0.2s',
                                }}
                            >
                                {polyglot.t('signal.addCrypto')}
                            </button>
                        </Card.Body>
                    </Card>
                </div>
            )}
        </section>
    );
};

export default SignalData;
