import AppRoutes from "./AppRoutes";
import PolyglotProvider from "./components/PolyglotProvider";
import { NotificationProvider } from "./contexts/NotificationContext";
import { ToastContainer } from 'react-toastify';
import 'react-toastify/dist/ReactToastify.css';
import { isDarkModeEnabled } from './settings';
import React, { useMemo, useEffect } from 'react';
import { Capacitor } from '@capacitor/core';
import { AdMob } from '@capacitor-community/admob';

const App = () => {
  const darkMode = isDarkModeEnabled();
  const toastTheme = useMemo(() => (darkMode ? 'dark' : 'light'), [darkMode]);

  useEffect(() => {
    const initializeAdMob = async () => {
      // Solo corremos la maquinaria pesada de Google AdMob si el usuario está en Android/iOS (No PWA web)
      if (Capacitor.isNativePlatform()) {
        try {
          await AdMob.initialize({
            requestTrackingAuthorization: true,
            initializeForTesting: process.env.NODE_ENV !== 'production'
          });
          console.log('AdMob inicializado correctamente ✅');

          // Escuchar eventos de diagnóstico
          await AdMob.addListener('bannerAdLoaded', () => {
            console.log('Google AdMob: Banner cargado exitosamente! 🚀');
          });

          await AdMob.addListener('bannerAdFailedToLoad', (info) => {
            console.error('Google AdMob: Error de carga:', JSON.stringify(info));
          });

          // Mostramos el banner con un pequeño retraso para asegurar que la vista nativa esté lista
          setTimeout(async () => {
            try {
              // ID DE PRUEBA OFICIAL DE GOOGLE (Para verificar si el código funciona)
              const TEST_AD_ID = 'ca-app-pub-3940256099942544/6300978111';
              
              // Cambiado a "false" para usar los IDs reales de Google
              const USE_TEST_ADS = false; 

              const adUnitId = USE_TEST_ADS 
                ? TEST_AD_ID 
                : (process.env.REACT_APP_ADMOB_AD_UNIT_ID || '');

              await AdMob.showBanner({
                adId: adUnitId.trim(),
                adSize: 'ADAPTIVE_BANNER',
                position: 'BOTTOM_CENTER',
                margin: 0,
                isTesting: USE_TEST_ADS // Importante: true para test ids
              });
              console.log(`AdMob Global Banner (${USE_TEST_ADS ? 'TEST' : 'PROD'}) solicitado ✅`);
            } catch (innerError) {
              console.error('Error mostrando el banner de AdMob:', innerError);
            }
          }, 1500); // 1.5 segundos de cortesía tras inicialización
        } catch (error) {
          console.error('Error inicializando o mostrando AdMob ❌', error);
        }
      }
    };

    initializeAdMob();
  }, []);
  return (
    <PolyglotProvider>
      <NotificationProvider>
        <>
          <AppRoutes />
          <ToastContainer position="top-center" autoClose={3500} theme={toastTheme} />
        </>
      </NotificationProvider>
    </PolyglotProvider>
  );
}

export default App;