import React from 'react';
import { useEffect, useState } from 'react';
import { isDarkModeEnabled, getNotificationsQueue, clearNotificationsQueue } from '../settings';
import CryptoLogo from './CryptoLogo';
import { useNavigate } from 'react-router-dom';
import './NotificationsPanel.css';

const NotificationsPanel = ({ visible, onClose, bellRef, polyglot, setNotificationCount }) => {
  const [panelPos, setPanelPos] = useState({ top: 80, left: '50%' });
  const [notifications, setNotifications] = useState([]);
  const darkMode = isDarkModeEnabled();
  const navigate = useNavigate();

  useEffect(() => {
    if (visible && bellRef && bellRef.current) {
      const rect = bellRef.current.getBoundingClientRect();
      setPanelPos({
        top: rect.bottom + 12,
        left: rect.left + rect.width / 2,
      });
    }
    // Read notifications from localStorage when panel opens
    if (visible) {
      setNotifications(getNotificationsQueue());
    }
  }, [visible, bellRef]);

  // Animation state
  const [show, setShow] = useState(false);

  useEffect(() => {
    if (visible) {
      setShow(true);
    } else {
      // Delay unmount for fade-out
      const timeout = setTimeout(() => {
        setShow(false);
        clearNotificationsQueue();
        if (typeof setNotificationCount === 'function') {
          setNotificationCount(0);
        }
      }, 250);
      return () => clearTimeout(timeout);
    }
  }, [visible]);

  if (!visible && !show) return null;

  // Overlay
  return (
    <div
      className={`notifications-overlay${visible ? ' notifications-overlay--visible' : ''}`}
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100vw',
        height: '100vh',
  background: darkMode ? 'rgba(16,22,36,0.85)' : 'rgba(0,0,0,0.6)',
        zIndex: 1000,
      }}
      onClick={e => {
        // Only close if clicking the overlay, not the panel
        if (e.target === e.currentTarget) {
          onClose && onClose();
        }
      }}
    >
      {/* Floating Panel anchored to bell */}
      <div
        className={`notifications-panel${visible ? ' notifications-panel--visible' : ''}`}
        style={{
          position: 'absolute',
          top: panelPos.top,
          left: panelPos.left,
          background: darkMode ? '#18213a' : '#fff',
          color: darkMode ? '#e0e6f0' : '#222',
          borderRadius: 16,
          boxShadow: darkMode
            ? '0 4px 24px rgba(0,0,0,0.7)'
            : '0 4px 24px rgba(0,0,0,0.3)',
          minWidth: 320,
          maxWidth: 400,
          padding: 24,
          fontFamily: 'inherit',
          fontSize: 16,
          display: 'flex',
          flexDirection: 'column',
          gap: 8,
        }}
      >
        <div style={{
          display: 'flex',
          flexDirection: 'column',
          gap: 12,
          maxHeight: 400,
          overflowY: 'auto',
        }}>
          {notifications.length === 0 ? (
            <div style={{ color: darkMode ? '#a0aec0' : '#888', fontStyle: 'italic', textAlign: 'center', padding: '32px 0' }}>
              {polyglot.t('notifications.empty')}
            </div>
          ) : (
            notifications.map((notif, idx) => {
              // Convert notification to expected details payload
              const signalPayload = {
                market: notif.market || 'USD_M_FUTURES',
                price: notif.price || 0,
                signal: notif.last_signal || '',
                signalReason: notif.signal_reason || '',
                stopLoss: notif.stop_loss || 0,
                symbol: notif.symbol || '',
                takeProfit: notif.take_profit || 0,
                timeframe: notif.timeframe || '',
              };
              return (
                <div
                  key={notif.id || idx}
                  style={{
                    background: darkMode ? '#22304a' : '#f7f9fc',
                    borderRadius: 10,
                    boxShadow: darkMode ? '0 2px 8px rgba(0,0,0,0.4)' : '0 2px 8px rgba(0,0,0,0.1)',
                    padding: '16px 12px',
                    border: darkMode ? '1px solid #2c3442' : '1px solid #e3e8ee',
                    display: 'flex',
                    flexDirection: 'row',
                    alignItems: 'center',
                    gap: 12,
                    cursor: 'pointer',
                    transition: 'background 0.2s',
                  }}
                  tabIndex={0}
                  role="button"
                  aria-label={polyglot.t('notifications.goToDetails', { symbol: notif.symbol })}
                  onClick={() => {
                    navigate('/details', { state: { signal: signalPayload, lastUpdatedAt: notif.time } });
                    onClose && onClose();
                  }}
                  onKeyDown={e => {
                    if (e.key === 'Enter' || e.key === ' ') {
                      navigate('/details', { state: { signal: signalPayload, lastUpdatedAt: notif.time } });
                      onClose && onClose();
                    }
                  }}
                >
                  {/* Crypto Icon */}
                  <div style={{ width: 32, height: 32, flexShrink: 0 }}>
                    <CryptoLogo cryptoPairName={notif.symbol} />
                  </div>
                  {/* Notification Details */}
                  <div style={{ display: 'flex', flexDirection: 'column', gap: 2, flex: 1 }}>
                    {/* Market Name */}
                    <div style={{ fontWeight: 600, fontSize: 16, display: 'flex', alignItems: 'center', gap: 8 }}>
                      {notif.symbol ? polyglot.t('cryptoPairs.' + notif.symbol) : notif.market || notif.symbol || polyglot.t('notifications.defaultTitle')}
                    </div>
                    {/* Signal & Reason */}
                    <div style={{ fontSize: 14, color: darkMode ? '#cbd5e1' : '#444', display: 'flex', gap: 8 }}>
                        <span style={{ fontWeight: 500 }}>
                            {polyglot.t('signal.value.' + (notif.last_signal))}
                        </span>
                        <span style={{ color: darkMode ? '#a0aec0' : '#888' }}>
                          {polyglot.t('signal.reason.' + (notif.signal_reason) + '.' + (notif.last_signal))}
                        </span>
                    </div>
                    {/* Message */}
                    {notif.message && (
                      <div style={{ fontSize: 13, color: darkMode ? '#bfcbe0' : '#666', marginTop: 2 }}>
                        {notif.message}
                      </div>
                    )}
                    {/* Time */}
                    {notif.time && (
                      <div style={{ fontSize: 12, color: darkMode ? '#7e8ca0' : '#888', marginTop: 2 }}>
                        {new Date(notif.time).toLocaleString()}
                      </div>
                    )}
                  </div>
                </div>
              );
            })
          )}
        </div>
  {/* Close button removed; panel is now only closable by clicking outside */}
      </div>
    </div>
  );
};

export default NotificationsPanel;
