import React, { useEffect, useState } from "react";
import { Card, Row, Col, Spinner, Container } from "react-bootstrap";
import { getAllNotificationsConfigs, deleteNotificationConfig } from "../api";
import ConfirmNotificationRemovalModal from "../components/ConfirmNotificationRemovalModal";
import { getUserData } from "../jerryTokenUtil";
import { isDarkModeEnabled, saveDarkMode } from "../settings";
import { Switch, FormControlLabel } from '@mui/material';
import { FaBell, FaTrashAlt } from "react-icons/fa";
import BackButton from "../components/BackButton";
import TelegramConfig from "../components/TelegramConfig";

const Settings = ({ polyglot }) => {
  useEffect(() => {
    const fetchConfigs = async () => {
      try {
        setLoading(true);
        const token = localStorage.getItem("jerryToken");
        const result = await getAllNotificationsConfigs(token);
        setConfigs(result || []);
      } catch (err) {
        setError(err.message || polyglot.t("settings.errorLoading"));
      } finally {
        setLoading(false);
      }
    };
    fetchConfigs();
  }, []);
  const [configs, setConfigs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  // Modal state for confirmation
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [pendingRemoveConfig, setPendingRemoveConfig] = useState(null);

  const handleRemoveClick = (id) => {
    const cfg = configs.find((cfg, idx) => (cfg.crypto_pair + cfg.market_name + cfg.timeframe + idx) === id);
    if (!cfg) return;
    setPendingRemoveConfig(cfg);
    setShowConfirmModal(true);
  };

  const handleConfirmRemove = async () => {
    if (!pendingRemoveConfig) return;
    setShowConfirmModal(false);
    setLoading(true);
    setError(null);
    const token = localStorage.getItem("jerryToken");
    try {
      await deleteNotificationConfig(token, pendingRemoveConfig.crypto_pair, pendingRemoveConfig.market_name, pendingRemoveConfig.timeframe);
      // Refresh configs after deletion
      const result = await getAllNotificationsConfigs(token);
      setConfigs(result || []);
    } catch (err) {
      setError(err.message || polyglot.t("settings.errorRemoving"));
    } finally {
      setLoading(false);
      setPendingRemoveConfig(null);
    }
  };
  const [darkMode, setDarkMode] = useState(isDarkModeEnabled());

  // Dark mode toggle logic
  const handleDarkModeToggle = () => {
    setDarkMode((prev) => !prev);
    saveDarkMode(!darkMode);
  };

  const userData = getUserData();

  return (
    <Container
      className={`notifications-container${darkMode ? ' profile-dark' : ''}`}
      style={{
        ...(darkMode ? {
          background: '#101624',
          color: '#e0e6f0',
          borderRadius: '12px',
          boxShadow: '0 2px 16px 0 rgba(16,22,36,0.4)',
          minHeight: 'calc(100vh - 120px)',
          paddingBottom: '2rem'
        } : { color: '#222', minHeight: 'calc(100vh - 120px)', paddingBottom: '2rem' }),
        maxWidth: '1400px',
        margin: '1.5rem auto',
        padding: '0 20px',
        border: 'none'
      }}
    >
      <div className="mb-4 pt-2">
        <BackButton polyglot={polyglot} />
      </div>

      <div className="row g-4">
        {/* SIDEBAR: Appearance & Controls */}
        <aside className="col-md-4 col-lg-3">
          <div style={{
            position: 'sticky',
            top: '20px',
            display: 'flex',
            flexDirection: 'column',
            gap: '20px'
          }}>
            {/* Appearance Card */}
            <div style={{
              background: darkMode ? '#18213a' : '#f8fafc',
              borderRadius: '16px',
              padding: '24px',
              border: darkMode ? '1px solid rgba(44, 62, 80, 0.6)' : '1px solid #e2e8f0',
              marginBottom: '20px'
            }}>
              <h6 style={{ fontWeight: 700, marginBottom: '20px', opacity: 0.8, textTransform: 'uppercase', fontSize: '0.75rem' }}>
                {polyglot.t("settingsPage.appearanceTitle")}
              </h6>
              <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <span style={{ fontWeight: 600, fontSize: '0.95rem' }}>{polyglot.t('profile.settings.darkMode')}</span>
                <Switch checked={darkMode} onChange={handleDarkModeToggle} color="primary" />
              </div>
            </div>

            {/* Telegram Config */}
            <TelegramConfig polyglot={polyglot} darkMode={darkMode} />

            {/* Plan Info */}
            <div style={{
              background: darkMode ? '#141c2f' : '#f1f5f9',
              borderRadius: '16px',
              padding: '24px',
              border: darkMode ? '1px solid rgba(44, 62, 80, 0.4)' : '1px solid #e2e8f0',
              opacity: 0.9
            }}>
              <h6 style={{ fontWeight: 700, marginBottom: '12px', opacity: 0.8, textTransform: 'uppercase', fontSize: '0.75rem' }}>
                {polyglot.t("profile.plan.title") || 'Account Plan'}
              </h6>
              <div style={{ fontSize: '0.9rem', fontWeight: 600 }}>
                {userData?.plan?.toUpperCase() || 'FREE'}
              </div>
            </div>
          </div>
        </aside>

        {/* MAIN CONTENT: Notifications List */}
        <main className="col-md-8 col-lg-9">
          <div style={{ marginBottom: '1.5rem' }}>
            <div style={{
              background: darkMode ? 'rgba(24, 33, 58, 0.2)' : '#f8fafc',
              border: darkMode ? '1px solid rgba(44, 62, 80, 0.4)' : '1px solid #e2e8f0',
              borderRadius: '20px',
              padding: '24px',
              minHeight: '440px',
              display: 'flex',
              flexDirection: 'column'
            }}>
              <h6 style={{ fontWeight: 700, marginBottom: '24px', opacity: 0.8, textTransform: 'uppercase', fontSize: '0.75rem' }}>
                {polyglot.t("settings.notificationsEnabledTitle")}
              </h6>

              {loading ? (
                <div style={{ textAlign: "center", padding: "4rem 0", flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                  <Spinner animation="border" variant={darkMode ? "light" : "primary"} />
                  <div style={{ marginTop: 12, opacity: 0.6 }}>{polyglot.t("label.loading")}</div>
                </div>
              ) : error ? (
                <div style={{ color: "#e57373", textAlign: "center", padding: "2rem", flex: 1, display: 'flex', flexDirection: 'column', justifyContent: 'center' }}>
                  <div style={{ fontSize: '2rem', marginBottom: '1rem' }}>⚠️</div>
                  {polyglot.t("notifications.error")}
                </div>
              ) : configs.length === 0 ? (
                <div style={{
                  padding: '4rem 2rem',
                  textAlign: 'center',
                  flex: 1,
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'center',
                  border: darkMode ? '1px dashed rgba(44, 62, 80, 0.6)' : '1px dashed #cbd5e1',
                  borderRadius: '16px'
                }}>
                  <div style={{ fontSize: '3rem', marginBottom: '1.5rem', opacity: 0.3 }}>🔕</div>
                  <h5 style={{ fontWeight: 600, color: darkMode ? '#e0e6f0' : '#334155', marginBottom: '0.5rem' }}>
                    {polyglot.t("notifications.empty")}
                  </h5>
                  <p style={{ margin: 0, fontSize: '0.95rem', color: darkMode ? '#94a3b8' : '#64748b' }}>
                    {polyglot.t("notifications.emptyDesc")}
                  </p>
                </div>
              ) : (
                <Row xs={1} lg={2} xl={3} className="g-3">
                  {configs.map((cfg, idx) => {
                    const symbol = cfg.crypto_pair;
                    const market = cfg.market_name;
                    const timeframe = cfg.timeframe;
                    const types = [
                      cfg.notify_trend ? { key: 'trend', icon: '📈' } : null,
                      cfg.notify_reversal ? { key: 'reversal', icon: '🔄' } : null,
                      cfg.notify_spike ? { key: 'spike', icon: '🚀' } : null
                    ].filter(Boolean);

                    return (
                      <Col key={symbol + market + timeframe + idx}>
                        <div style={{
                          background: darkMode ? '#141c2f' : '#ffffff',
                          borderRadius: '16px',
                          padding: '20px',
                          border: darkMode ? '1px solid rgba(44, 62, 80, 0.6)' : '1px solid #e2e8f0',
                          boxShadow: '0 2px 8px rgba(0,0,0,0.02)',
                          transition: 'transform 0.2s ease',
                          height: '100%',
                          display: 'flex',
                          flexDirection: 'column',
                          justifyContent: 'space-between',
                          position: 'relative'
                        }}
                        onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-2px)'; }}
                        onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0)'; }}
                        >
                          <div>
                            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '12px' }}>
                              <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                                <div style={{ 
                                  background: darkMode ? '#22304a' : '#f1f5f9',
                                  width: '32px',
                                  height: '32px',
                                  borderRadius: '8px',
                                  display: 'flex',
                                  alignItems: 'center',
                                  justifyContent: 'center'
                                }}>
                                  <FaBell size={14} style={{ color: darkMode ? '#4fd1c5' : '#2563eb' }} />
                                </div>
                                <div>
                                  <div style={{ fontWeight: 700, fontSize: '0.95rem' }}>{polyglot.t(`cryptoPairs.${symbol}`)}</div>
                                  <div style={{ fontSize: '0.75rem', opacity: 0.6 }}>{polyglot.t(`markets.${market}`)}</div>
                                </div>
                              </div>
                              <span style={{ 
                                background: darkMode ? '#22304a' : '#f1f5f9',
                                color: darkMode ? '#e0e6f0' : '#475569',
                                padding: '2px 8px',
                                borderRadius: '6px',
                                fontSize: '0.75rem',
                                fontWeight: 700
                              }}>
                                {timeframe}
                              </span>
                            </div>

                            <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginTop: '12px' }}>
                              {types.length === 0 ? (
                                <span style={{ fontSize: '0.8rem', opacity: 0.5 }}>{polyglot.t("notifications.none")}</span>
                              ) : (
                                types.map(t => (
                                  <div key={t.key} style={{ 
                                    display: 'flex', 
                                    alignItems: 'center', 
                                    gap: '4px',
                                    background: darkMode ? 'rgba(79, 209, 197, 0.1)' : 'rgba(37, 99, 235, 0.05)',
                                    padding: '4px 8px',
                                    borderRadius: '6px',
                                    fontSize: '0.75rem',
                                    fontWeight: 600,
                                    color: darkMode ? '#4fd1c5' : '#2563eb'
                                  }}>
                                    <span>{t.icon}</span>
                                    <span>{polyglot.t(`signal.reason.${t.key}.label`)}</span>
                                  </div>
                                ))
                              )}
                            </div>
                          </div>

                          <div style={{ marginTop: '20px', display: 'flex', justifyContent: 'flex-end', borderTop: darkMode ? '1px solid rgba(44, 62, 80, 0.3)' : '1px solid #f1f5f9', paddingTop: '12px' }}>
                            <button 
                              onClick={() => handleRemoveClick(symbol + market + timeframe + idx)}
                              style={{
                                background: 'transparent',
                                border: 'none',
                                color: '#ef4444',
                                fontSize: '0.85rem',
                                fontWeight: 600,
                                display: 'flex',
                                alignItems: 'center',
                                gap: '6px',
                                padding: '4px 8px',
                                borderRadius: '6px',
                                transition: 'background 0.2s'
                              }}
                              onMouseEnter={(e) => { e.currentTarget.style.background = darkMode ? 'rgba(239, 68, 68, 0.1)' : 'rgba(239, 68, 68, 0.05)'; }}
                              onMouseLeave={(e) => { e.currentTarget.style.background = 'transparent'; }}
                            >
                              <FaTrashAlt size={12} />
                              {polyglot.t("settings.remove") || 'Remove'}
                            </button>
                          </div>
                        </div>
                      </Col>
                    );
                  })}
                </Row>
              )}
            </div>
          </div>
        </main>
      </div>

      {/* Confirmation Modal for Notification Removal */}
      <ConfirmNotificationRemovalModal
        show={showConfirmModal}
        onHide={() => setShowConfirmModal(false)}
        onConfirm={handleConfirmRemove}
        config={pendingRemoveConfig || {}}
        polyglot={polyglot}
        darkMode={darkMode}
      />
    </Container>
  );
};

export default Settings;
