import { useState, useEffect } from 'react';
import { Container, Row, Col } from 'react-bootstrap';
import CryptoItem from '../components/CryptoItem';
import { fetchCryptos } from '../api';
import useSessionExpired from '../hooks/useSessionExpired';
import { useNavigate } from 'react-router-dom';
import {getUserData} from '../jerryTokenUtil'
import BackButton from '../components/BackButton';
import { isDarkModeEnabled } from '../settings';

const AddCryptoPage = ({ polyglot }) => {
  const [cryptos, setCryptos] = useState([]); 
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const SessionExpiredModal = useSessionExpired(polyglot);
  const navigate = useNavigate();
  const userData = getUserData();

  const cryptosDataKey = `${userData.hashedEmail}.cryptosData`;

  // Scroll to top on mount
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'auto' });
  }, []);

  useEffect(() => {
    const loadCryptos = async () => {
      try {
        const storedCryptosData = sessionStorage.getItem(cryptosDataKey);

        if (storedCryptosData) {
          setCryptos(JSON.parse(storedCryptosData));
          return;
        }

        const jerryToken = localStorage.getItem('jerryToken');
        const cryptosData = await fetchCryptos(jerryToken);
        sessionStorage.setItem(cryptosDataKey, JSON.stringify(cryptosData));
        setCryptos(cryptosData || []);
      } catch (err) {
        setError(err.message || polyglot.t('settingsPage.failedToLoad'));
      } finally {
        setLoading(false);
      }
    };

    loadCryptos();
  }, []);

  const onMarketAdded = (newMarket) => {
    const marketName = polyglot.t(`markets.${newMarket.market_name}`);

    navigate('/main', {state: { 
        alert: polyglot.t('settingsPage.following', {
            crypto: newMarket.pair_name,
            timeframe: newMarket.timeframe,
            market: marketName
        }) 
    }})
  };

  const darkMode = isDarkModeEnabled();
  const darkBg = '#101624'; // blueish, near-black
  const darkCard = '#18213a';
  const darkBorder = 'rgba(44, 62, 80, 0.6)';
  const darkText = '#e0e6f0';

  return (
    <Container className="mt-4" style={darkMode ? {
      background: darkBg,
      color: darkText,
      borderRadius: '12px',
      boxShadow: '0 2px 16px 0 rgba(16,22,36,0.4)'
    } : {}}>
      <Row className="mb-3" style={darkMode ? { color: darkText } : {}}>
        <Col xs="auto">
          <BackButton polyglot={polyglot} />
        </Col>
      </Row>

      {/* Conditional content rendering */}
      {loading && (
        <div className="d-flex justify-content-center" style={darkMode ? { color: darkText } : {}}>
          <span>{polyglot.t('label.loading')}</span>
        </div>
      )}

      {!loading && error && (
        <div className="text-center text-danger" style={darkMode ? { color: '#e57373' } : {}}>
          {(() => {
            const err = (typeof error === 'string' ? error : (error?.message || ''));
            const key = `error.${err.toLowerCase()}`;
            return polyglot.t(key) !== key ? polyglot.t(key) : (polyglot.t(err) || err);
          })()}
        </div>
      )}

      {!loading && !error && (
        <section>
          <Row className="g-3 g-md-4 mt-3 pb-4">
            {(cryptos || [])
              .sort((a, b) => a.base_currency.localeCompare(b.base_currency))
              .map((crypto, index) => (
                <Col key={index} xs={4} sm={4} md={3} lg={2} className="d-flex align-items-stretch" style={darkMode ? { color: darkText } : {}}>
                  <CryptoItem
                    crypto={crypto}
                    polyglot={polyglot}
                    onMarketAdded={onMarketAdded}
                    darkMode={darkMode}
                  />
                </Col>
              ))}
          </Row>
        </section>
      )}

      {SessionExpiredModal}
    </Container>
  );
};

export default AddCryptoPage;
