import React, { useState, useEffect, useContext, useRef } from 'react';
import { FaCog, FaBell } from 'react-icons/fa';
import { NotificationContext } from '../contexts/NotificationContext';
import { basepath } from './Header';
import { useNavigate } from 'react-router-dom';
import { isDarkModeEnabled, saveNotificationsQueue, getNotificationsQueue, clearNotificationsQueue } from '../settings';
import { getUserData } from '../jerryTokenUtil';
import NotificationsPanel from '../components/NotificationsPanel';
import { Capacitor } from '@capacitor/core';

const SmallHeader = ({ 
  polyglot, 
}) => {
    // const { logout } = useAuth0();
    // const [showConfirmLogout, setShowConfirmLogout] = useState(false);
    const navigate = useNavigate();
    const [mode, setMode] = useState(isDarkModeEnabled());

    useEffect(() => {
        const interval = setInterval(() => {
            setMode(isDarkModeEnabled());
        }, 300);
        return () => clearInterval(interval);
    }, []);

    const darkMode = mode;
    const darkBg = '#0b101a'; // even darker for header/footer
    const darkBorder = 'rgba(44, 62, 80, 0.6)';
    const darkText = '#e0e6f0';
    const bannerUrl = `${basepath}/assets/banner.svg`;
    const user = getUserData();
    
    // Mobile detection using Capacitor
    const isMobile = Capacitor.isNativePlatform();


    // Notification bell logic
    const { queue } = useContext(NotificationContext) || { queue: [] };
    const [notifCount, setNotifCount] = useState(0);
    const [panelVisible, setPanelVisible] = useState(false);
    const bellRef = useRef();

    // Notification count logic
    const prevQueueLengthRef = useRef(0);
    useEffect(() => {
        // On mount, initialize notifCount from localStorage
        const arr = getNotificationsQueue();
        setNotifCount(arr.length);
        prevQueueLengthRef.current = Array.isArray(queue) ? queue.length : 0;
    }, []);

    useEffect(() => {
        if (Array.isArray(queue)) {
            // Only increment notifCount when new notifications arrive
            if (queue.length > prevQueueLengthRef.current) {
                // Save only new notifications
                for (let i = prevQueueLengthRef.current; i < queue.length; i++) {
                    saveNotificationsQueue(queue[i]);
                }
                // Update notifCount based on new length
                // setNotifCount(queue.length);
            }
            prevQueueLengthRef.current = queue.length;
            setNotifCount(getNotificationsQueue().length);
        }
    }, [queue]);

    const handleBellClick = () => {
        setPanelVisible(true);
    };

    const handleGearClick = () => {
        navigate('/settings');
    };

    return (
        <div>
            {/* Small Header */}
            <div 
                className="smaller-header text-center" 
                style={darkMode ? {
                    backgroundColor: darkBg,
                    color: darkText,
                    borderBottom: `1px solid ${darkBorder}`,
                    fontSize: '14px',
                    width: '100%'
                } : {
                    backgroundColor: '#e0d7d4',
                    color: '#222',
                    borderBottom: '1px solid #ddd',
                    fontSize: '14px',
                    width: '100%'
                }}
            >
                <div style={{
                    maxWidth: '1400px',
                    margin: '0 auto',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    width: '100%',
                    paddingTop: 'calc(8px + env(safe-area-inset-top, 0px))',
                    paddingBottom: '8px',
                    paddingLeft: '20px',
                    paddingRight: '20px',
                }}>
                    <div
                        onClick={() => navigate('/main')} 
                        style={{ display: 'flex', alignItems: 'center', cursor: 'pointer' }} >
                        {/* Logo */}
                        <img 
                            src={bannerUrl} 
                            alt="Jerry" 
                            style={{ width: '70px', height: '35px', marginRight: '10px' }} 
                        />
                    </div>
                    {/* User Email */}
                    <div style={{ display: 'flex', alignItems: 'center' }}>
                        {/* Bell Icon with notification bubble */}
                        <div ref={bellRef} style={{ position: 'relative', marginRight: '18px', cursor: 'pointer', display: 'flex', alignItems: 'center' }} onClick={handleBellClick} title="Notifications">
                            <FaBell size={22} color={darkMode ? '#ffffff' : '#000000'} />
                            {notifCount > 0 && (
                                <span style={{
                                    position: 'absolute',
                                    top: -6,
                                    right: -6,
                                    background: '#e57373',
                                    color: '#fff',
                                    borderRadius: '50%',
                                    padding: '2px 7px',
                                    fontSize: '0.85rem',
                                    fontWeight: 700,
                                    boxShadow: '0 1px 4px rgba(0,0,0,0.15)',
                                    zIndex: 2
                                }}>{notifCount}</span>
                            )}
                        </div>
                        {/* Gear Icon */}
                        <div style={{ marginRight: '12px', cursor: 'pointer', display: 'flex', alignItems: 'center' }} onClick={handleGearClick} title="Settings">
                            <FaCog size={22} color={darkMode ? darkText : '#333'} />
                        </div>
                        <small>
                            <img 
                                src={user?.picture}
                                alt={user?.email}
                                style={{ 
                                    width: '35px', 
                                    height: '35px', 
                                    marginRight: '10px', 
                                    borderRadius: '50%', 
                                    objectFit: 'cover',
                                    cursor: 'pointer',
                                    border: darkMode ? `1.5px solid ${darkBorder}` : undefined,
                                    background: darkMode ? darkBg : undefined
                                  }} 
                                onClick={() => navigate('/profile')}
                            />
                        </small>
                    </div>
                </div>
            </div>

            {/* Notifications Panel */}
            <NotificationsPanel
                visible={panelVisible}
                onClose={() => setPanelVisible(false)}
                bellRef={bellRef}
                polyglot={polyglot}
                setNotificationCount={setNotifCount}
            />

            {/* Logout confirmation modal removed, now in Profile page */}

        </div>
    );
};

export default SmallHeader;
