import React, { createContext, useState, useEffect, useCallback } from "react";

export const NotificationContext = createContext();

export const NotificationProvider = ({ children }) => {
  const [queue, setQueue] = useState([]);

  useEffect(() => {
    function handleMessage(event) {
      console.log("Push notification received in React app:", event.data);
      setQueue((prev) => [...prev, event.data]);
    }
    if ("serviceWorker" in navigator) {
      navigator.serviceWorker.addEventListener("message", handleMessage);
    }
    return () => {
      if ("serviceWorker" in navigator) {
        navigator.serviceWorker.removeEventListener("message", handleMessage);
      }
    };
  }, []);

  // Show the first notification in the queue
  const notification = queue.length > 0 ? queue[0] : null;

  // Remove the first notification from the queue
  const closeNotification = useCallback(() => {
    setQueue((prev) => prev.slice(1));
  }, []);

  return (
    <NotificationContext.Provider value={{ notification, closeNotification, queue }}>
      {children}
    </NotificationContext.Provider>
  );
};
