import React, { useEffect, useContext, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Container, Card, Button } from 'react-bootstrap';
import { PolyglotContext } from '../components/PolyglotProvider';
import { isDarkModeEnabled } from '../settings';
import { CheckCircle, ArrowRight, PartyPopper } from 'lucide-react';
import { clearSessionCache } from '../sessionCache';

const PaymentSuccess = () => {
    const navigate = useNavigate();
    const { polyglot } = useContext(PolyglotContext);
    const darkMode = isDarkModeEnabled();
    const [animate, setAnimate] = useState(false);

    useEffect(() => {
        setAnimate(true);

        // Clear potential local caches that might need refresh after an upgrade
        clearSessionCache();
    }, []);

    return (
        <Container className="d-flex align-items-center justify-content-center" style={{ minHeight: '80vh', padding: '1rem' }}>
            <Card style={{
                background: darkMode ? 'linear-gradient(145deg, #18213a, #101624)' : '#ffffff',
                color: darkMode ? '#e0e6f0' : '#222',
                border: darkMode ? '1px solid #22304a' : '1px solid #eef2f7',
                borderRadius: '24px',
                maxWidth: '550px',
                width: '100%',
                padding: '3rem 2rem',
                boxShadow: darkMode ? '0 20px 40px rgba(0,0,0,0.4)' : '0 20px 40px rgba(0,0,0,0.05)',
                transition: 'all 0.5s ease-out',
                transform: animate ? 'translateY(0)' : 'translateY(20px)',
                opacity: animate ? 1 : 0
            }}>
                <div className="text-center">
                    <div style={{ position: 'relative', display: 'inline-block', marginBottom: '2rem' }}>
                        <div style={{
                            position: 'absolute',
                            top: '50%',
                            left: '50%',
                            transform: 'translate(-50%, -50%)',
                            width: '120px',
                            height: '120px',
                            background: darkMode ? 'rgba(40, 167, 69, 0.1)' : 'rgba(40, 167, 69, 0.05)',
                            borderRadius: '50%',
                            animation: 'pulse 2s infinite'
                        }} />
                        <CheckCircle size={90} color="#28a745" style={{
                            position: 'relative',
                            filter: 'drop-shadow(0 4px 10px rgba(40, 167, 69, 0.3))'
                        }} />
                    </div>

                    <h1 style={{
                        fontWeight: 800,
                        marginBottom: '1rem',
                        fontSize: '2.2rem',
                        background: darkMode ? 'linear-gradient(to right, #fff, #8fa3c8)' : 'linear-gradient(to right, #101624, #444)',
                        WebkitBackgroundClip: 'text',
                        WebkitTextFillColor: 'transparent'
                    }}>
                        {polyglot.t('payment.success.title')}
                    </h1>

                    <p style={{
                        fontSize: '1.2rem',
                        color: darkMode ? '#8fa3c8' : '#555',
                        marginBottom: '1rem',
                        lineHeight: '1.6'
                    }}>
                        {polyglot.t('payment.success.description')}
                    </p>

                    <div style={{
                        background: darkMode ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.02)',
                        padding: '1.5rem',
                        borderRadius: '16px',
                        marginBottom: '2.5rem',
                        border: darkMode ? '1px dashed #22304a' : '1px dashed #e0e6f0'
                    }}>
                        <p style={{ margin: 0, fontSize: '1rem', color: darkMode ? '#8fa3c8' : '#666' }}>
                            <PartyPopper size={18} className="me-2" />
                            {polyglot.t('payment.success.message')}
                        </p>
                    </div>

                    <div className="d-grid gap-3">
                        <Button
                            variant="primary"
                            size="lg"
                            onClick={() => navigate('/main')}
                            style={{
                                fontWeight: 600,
                                padding: '1rem',
                                borderRadius: '8px',
                                display: 'flex',
                                alignItems: 'center',
                                justifyContent: 'center',
                                gap: '10px'
                            }}
                        >
                            {polyglot.t('payment.success.button')}
                            <ArrowRight size={20} />
                        </Button>
                    </div>
                </div>
            </Card>

            <style>{`
                @keyframes pulse {
                    0% { transform: translate(-50%, -50%) scale(0.9); opacity: 0.8; }
                    50% { transform: translate(-50%, -50%) scale(1.1); opacity: 0.4; }
                    100% { transform: translate(-50%, -50%) scale(0.9); opacity: 0.8; }
                }
            `}</style>
        </Container>
    );
};

export default PaymentSuccess;

