import { TrendingUp, TrendingDown, ArrowBigUpDash, ArrowBigDownDash, PauseCircle } from 'lucide-react';
import { isDarkModeEnabled } from "../settings";
import './SignalPill.css';

const SignalPill = ({ polyglot, signal }) => {
  const darkMode = isDarkModeEnabled();
  const isBuy = signal.signal === 'buy';
  const isSell = signal.signal === 'sell';
  const reason = signal.signalReason;
  let icon;

  if (reason === 'reversal') {
    icon = isBuy ? <ArrowBigUpDash className="w-4 h-4" /> : <ArrowBigDownDash className="w-4 h-4" />;
  } else if (reason === 'trend') {
    icon = isBuy ? <TrendingUp className="w-4 h-4" /> : <TrendingDown className="w-4 h-4" />;
  } else {
    icon = <PauseCircle className="w-4 h-4" />; // default/fallback icon
  }

  return (
    <span
      className={`signal-pill badge px-4 py-2${darkMode ? ' signal-pill-dark' : ''}${isBuy ? ' signal-pill-buy' : isSell ? ' signal-pill-sell' : ' signal-pill-hold'}`}
      style={{
        borderRadius: '999px',
        fontWeight: 600,
        fontSize: '1rem',
        display: 'inline-flex',
        alignItems: 'center',
        gap: '0.4em',
        boxShadow: darkMode ? '0 2px 8px 0 rgba(16,22,36,0.18)' : '0 2px 8px 0 rgba(110,110,110,0.10)',
        background: darkMode
          ? isBuy
            ? '#174c36' // darker green
            : isSell
              ? '#4c2323' // darker red
              : '#232a3a' // dark gray
          : isBuy
            ? '#d1fae5' // light green
            : isSell
              ? '#fee2e2' // light red
              : '#e0e6f0', // light gray
        color: darkMode
          ? isBuy
            ? '#4fc3a1' // green text
            : isSell
              ? '#e57373' // red text
              : '#8fa3c8' // gray text
          : isBuy
            ? '#047857'
            : isSell
              ? '#b91c1c'
              : '#22304a',
        border: darkMode
          ? isBuy
            ? '1.5px solid #2e7d5b'
            : isSell
              ? '1.5px solid #7d2e2e'
              : '1.5px solid #22304a'
          : '1.5px solid #e0e6f0',
        transition: 'background 0.2s, color 0.2s, border 0.2s',
        textDecoration: 'none',
      }}
    >
      {icon} {polyglot.t(`signal.value.${signal.signal}`)} {polyglot.t(`signal.reason.${reason}.${signal.signal}`)}
    </span>
  );
};

export default SignalPill;