import React, { useEffect, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Container, Row, Col, Card, Button, Badge } from 'react-bootstrap';
import { isDarkModeEnabled } from '../settings';
import BackButton from '../components/BackButton';
import { getPlans } from '../sessionCache';
import { basepath } from "./Header";

const Upgrade = ({ polyglot }) => {
  const navigate = useNavigate();
  const location = useLocation();
  const planKey = location.state?.plan;
  const [planConfig, setPlanConfig] = useState(null);
  const [loading, setLoading] = useState(true);
  const darkMode = isDarkModeEnabled();

  // Scroll to top on mount
  useEffect(() => {
    window.scrollTo({ top: 0, behavior: 'auto' });
  }, []);

  useEffect(() => {
    if (!planKey) {
      navigate('/main');
      return;
    }
    const fetchConfig = async () => {
      setLoading(true);
      try {
        const plans = await getPlans(basepath);
        setPlanConfig(plans[planKey]);
      } catch (e) {
        setPlanConfig(null);
      } finally {
        setLoading(false);
      }
    };
    fetchConfig();
  }, [planKey, navigate]);

  if (loading) {
    return (
      <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', height: '100vh' }}>
        <div className="d-flex justify-content-center">
          <div className="spinner-border text-primary" role="status">
            <span className="visually-hidden">{polyglot.t('loginPage.loading')}</span>
          </div>
        </div>
        <div className="mt-3">{polyglot.t('loginPage.verifying')}</div>
      </div>
    );
  }

  const planName = polyglot.t(`plan.${planKey}`);
  const planPrice = planConfig.price;
  const timeframes = planConfig.timeframes;
  const refreshIntervalSec = planConfig.refreshInternvalSec;
  const maxTrackedCryptos = planConfig.maxTrackedCryptos;
  const maxNotifications = planConfig.maxNotifications;
  const allowedMarkets = planConfig.allowed_markets;
  const allowedBaseCurrencies = planConfig.allowed_base_currencies;

  // Helper function to get timeframe display names
  const getTimeframeDisplay = (timeframe) => {
    return polyglot.t(`timeframes.${timeframe}`, timeframe);
  };

  // Helper function to get refresh interval display
  const getRefreshDisplay = (seconds) => {
    if (seconds < 60) return `${seconds} seconds`;
    if (seconds === 60) return '1 minute';
    if (seconds < 3600) return `${Math.floor(seconds / 60)} minutes`;
    return `${Math.floor(seconds / 3600)} hours`;
  };

  return (
    <Container className={darkMode ? 'profile-dark' : ''} style={darkMode ? {
      background: '#101624', color: '#e0e6f0', borderRadius: '12px', marginTop: '2rem', paddingBottom: '2rem',
    } : {
      background: '#fff', color: '#222', borderRadius: '12px', marginTop: '2rem', paddingBottom: '2rem',
    }}>
      <div className="mt-4">
        <BackButton polyglot={polyglot} />
      </div>
      
      {/* Header Section */}
      <div className="text-center mt-4 mb-5">
        <h1 style={{ 
          fontWeight: 700, 
          fontSize: '2.5rem',
          marginBottom: '0.5rem',
          color: darkMode ? '#e0e6f0' : '#222'
        }}>
          {planName}
        </h1>
        <p style={{ 
          fontSize: '1.1rem',
          color: darkMode ? '#8fa3c8' : '#666',
          marginBottom: '2rem'
        }}>
          {polyglot.t('upgrade.subtitle')}
        </p>
        <div style={{ 
          fontSize: '3rem', 
          fontWeight: 800,
          color: planKey === 'elite' ? '#ffc107' : planKey === 'pro' ? '#007bff' : '#28a745',
          marginBottom: '1rem'
        }}>
          {planPrice}
        </div>
      </div>

      <Row className="justify-content-center">
        <Col lg={8}>
          {/* Plan Features Card */}
          <Card className="mb-4" style={darkMode ? {
            background: '#18213a', color: '#e0e6f0', border: '1px solid #22304a',
          } : {
            background: '#fff', color: '#222', border: '1px solid #e0e6f0',
          }}>
            <Card.Header style={darkMode ? { 
              background: '#22304a', color: '#e0e6f0', borderBottom: '1px solid #22304a',
              fontSize: '1.3rem', fontWeight: 600
            } : { 
              background: '#f8f9fa', color: '#222', borderBottom: '1px solid #e0e6f0',
              fontSize: '1.3rem', fontWeight: 600
            }}>
              {polyglot.t('upgrade.features.title')}
            </Card.Header>
            <Card.Body>
              <ul style={{ listStyle: 'none', padding: 0, marginBottom: '1rem' }}>
                {['1', '2', '3', '4', '5'].map(featureKey => (
                  <li key={featureKey} style={{ marginBottom: 6, fontSize: '1.1rem', padding: '10px' }}>
                    <span style={{ color: '#28a745', marginRight: '10px' }}>✓</span>
                    {polyglot.t(`paywall.planDescriptions.${planKey}.${featureKey}`)}
                  </li>
                ))}
              </ul>
            </Card.Body>
          </Card>

          {/* Plan Comparison */}
          <Card className="mb-4" style={darkMode ? {
            background: '#18213a', color: '#e0e6f0', border: '1px solid #22304a',
          } : {
            background: '#fff', color: '#222', border: '1px solid #e0e6f0',
          }}>
            <Card.Header style={darkMode ? { 
              background: '#22304a', color: '#e0e6f0', borderBottom: '1px solid #22304a',
              fontSize: '1.3rem', fontWeight: 600
            } : { 
              background: '#f8f9fa', color: '#222', borderBottom: '1px solid #e0e6f0',
              fontSize: '1.3rem', fontWeight: 600
            }}>
              {polyglot.t('upgrade.benefits.title')}
            </Card.Header>
            <Card.Body>
              <ul style={{ 
                listStyle: 'none', 
                padding: 0,
                margin: 0
              }}>
                <li style={{ 
                  padding: '0.75rem 0',
                  borderBottom: `1px solid ${darkMode ? '#22304a' : '#e0e6f0'}`,
                  display: 'flex',
                  alignItems: 'center'
                }}>
                  <span style={{ 
                    color: '#28a745',
                    marginRight: '0.75rem',
                    fontSize: '1.2rem'
                  }}>✓</span>
                  {polyglot.t('upgrade.benefits.technicalAnalysis')}
                </li>
                <li style={{ 
                  padding: '0.75rem 0',
                  borderBottom: `1px solid ${darkMode ? '#22304a' : '#e0e6f0'}`,
                  display: 'flex',
                  alignItems: 'center'
                }}>
                  <span style={{ 
                    color: '#28a745',
                    marginRight: '0.75rem',
                    fontSize: '1.2rem'
                  }}>✓</span>
                  {polyglot.t('upgrade.benefits.realTimeData')}
                </li>
                <li style={{ 
                  padding: '0.75rem 0',
                  borderBottom: `1px solid ${darkMode ? '#22304a' : '#e0e6f0'}`,
                  display: 'flex',
                  alignItems: 'center'
                }}>
                  <span style={{ 
                    color: '#28a745',
                    marginRight: '0.75rem',
                    fontSize: '1.2rem'
                  }}>✓</span>
                  {polyglot.t('upgrade.benefits.tradingInsights')}
                </li>
                <li style={{ 
                  padding: '0.75rem 0',
                  display: 'flex',
                  alignItems: 'center'
                }}>
                  <span style={{ 
                    color: '#28a745',
                    marginRight: '0.75rem',
                    fontSize: '1.2rem'
                  }}>✓</span>
                  {planKey === 'elite' 
                    ? polyglot.t('upgrade.benefits.support.elite')
                    : polyglot.t('upgrade.benefits.support.default')
                  }
                </li>
              </ul>
            </Card.Body>
          </Card>

          {/* Action Button */}
          <div className="text-center">
            <Button 
              variant={planKey === 'elite' ? 'warning' : planKey === 'pro' ? 'primary' : 'success'}
              size="lg"
              style={{ 
                fontWeight: 600, 
                fontSize: '1.2rem',
                padding: '1rem 3rem',
                borderRadius: '8px'
              }}
              onClick={() => navigate('/payment', { state: { plan: planKey, planConfig } })}
            >
              {polyglot.t('upgrade.action.button', { plan: planName })}
            </Button>
            <p style={{ 
              fontSize: '0.9rem',
              color: darkMode ? '#8fa3c8' : '#666',
              marginTop: '1rem',
              marginBottom: 0
            }}>
              {polyglot.t('upgrade.action.trust')}
            </p>
          </div>
        </Col>
      </Row>
    </Container>
  );
};

export default Upgrade;
