import React from 'react';
import { Button } from 'react-bootstrap';

const ALL_MARKETS = ['SPOT', 'USD_M_FUTURES'];
const ALL_SIGNALS = ['buy', 'sell'];
const ALL_REASONS = ['spike', 'reversal', 'trend'];

function SignalFilters(props) {
  const {
    filters = { market: null, signal: null, reason: null },
    onChange,
    polyglot,
    darkMode,
    availableMarkets = ALL_MARKETS,
    availableSignals = ALL_SIGNALS,
    availableReasons = ALL_REASONS,
    onCountChange,
    isSidebar = false,
  } = props;

  const buttonStyle = (active, isClear = false) => ({
    fontWeight: isClear ? 500 : 700,
    fontSize: isSidebar ? '0.75rem' : '0.85rem',
    borderRadius: '8px',
    margin: 0,
    padding: isSidebar ? '6px 12px' : '8px 16px',
    minWidth: isSidebar ? 60 : 48,
    minHeight: isSidebar ? 32 : 40,
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: 6,
    background: active 
      ? (darkMode ? 'rgba(59, 130, 246, 0.2)' : 'rgba(37, 99, 235, 0.1)') 
      : (darkMode ? '#1e293b' : '#ffffff'),
    color: active 
      ? (darkMode ? '#60a5fa' : '#2563eb') 
      : (darkMode ? '#94a3b8' : '#64748b'),
    border: active 
      ? (darkMode ? '1px solid #3b82f6' : '1px solid #2563eb') 
      : (darkMode ? '1px solid #334155' : '1px solid #e2e8f0'),
    boxShadow: active ? 'none' : '0 1px 2px rgba(0,0,0,0.02)',
    transition: 'all 0.15s ease',
    flex: isSidebar ? '1 1 auto' : '1 1 0px',
    maxWidth: isSidebar ? '100%' : '200px',
    cursor: 'pointer',
    textTransform: 'uppercase',
    letterSpacing: '0.025em',
  });

  // Count selected filters
  const filterCount = [filters.market, filters.signal, filters.reason].filter(Boolean).length;
  // Notify parent of count change
  React.useEffect(() => {
    if (onCountChange) onCountChange(filterCount);
  }, [filterCount, onCountChange]);

  const f = filters;

  const GroupLabel = ({ label }) => (
    isSidebar ? (
      <div style={{ 
        width: '100%', 
        fontSize: '0.7rem', 
        fontWeight: 800, 
        opacity: 0.5, 
        textTransform: 'uppercase', 
        marginBottom: '6px', 
        textAlign: 'left',
        letterSpacing: '0.05em'
      }}>
        {label}
      </div>
    ) : null
  );

  return (
    <div style={{
      display: 'flex',
      flexDirection: isSidebar ? 'column' : 'row',
      flexWrap: 'wrap',
      gap: isSidebar ? 24 : 12,
      justifyContent: isSidebar ? 'flex-start' : 'center',
      marginBottom: 12,
    }}>
      {/* Market Group */}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, margin: 0, width: '100%', justifyContent: isSidebar ? 'flex-start' : 'center' }}>
        <GroupLabel label={polyglot.t('filters.market.label') || 'Market'} />
        {availableMarkets.map((market) => (
          <Button
            key={market}
            style={buttonStyle(f.market === market)}
            onClick={() => onChange({ ...f, market: f.market === market ? null : market })}
            aria-pressed={f.market === market}
            onMouseEnter={(e) => { 
                if (f.market !== market) e.currentTarget.style.background = darkMode ? '#2d3748' : '#f8fafc'; 
            }}
            onMouseLeave={(e) => { 
                if (f.market !== market) e.currentTarget.style.background = darkMode ? '#1e293b' : '#ffffff'; 
            }}
          >
            <span>{polyglot.t(`filters.market.${market}`)}</span>
          </Button>
        ))}
      </div>
      {/* Signal Group */}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, margin: 0, width: '100%', justifyContent: isSidebar ? 'flex-start' : 'center' }}>
        <GroupLabel label={polyglot.t('filters.signal.label') || 'Signal'} />
        {availableSignals.map((signal) => (
          <Button
            key={signal}
            style={buttonStyle(f.signal === signal)}
            onClick={() => onChange({ ...f, signal: f.signal === signal ? null : signal })}
            aria-pressed={f.signal === signal}
            onMouseEnter={(e) => { 
                if (f.signal !== signal) e.currentTarget.style.background = darkMode ? '#2d3748' : '#f8fafc'; 
            }}
            onMouseLeave={(e) => { 
                if (f.signal !== signal) e.currentTarget.style.background = darkMode ? '#1e293b' : '#ffffff'; 
            }}
          >
            <span>{polyglot.t(`filters.signal.${signal}`)}</span>
          </Button>
        ))}
      </div>
      {/* Reason Group */}
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6, margin: 0, width: '100%', justifyContent: isSidebar ? 'flex-start' : 'center' }}>
        <GroupLabel label={polyglot.t('filters.reason.label') || 'Reason'} />
        {availableReasons.map((reason) => (
          <Button
            key={reason}
            style={buttonStyle(f.reason === reason)}
            onClick={() => onChange({ ...f, reason: f.reason === reason ? null : reason })}
            aria-pressed={f.reason === reason}
            onMouseEnter={(e) => { 
                if (f.reason !== reason) e.currentTarget.style.background = darkMode ? '#2d3748' : '#f8fafc'; 
            }}
            onMouseLeave={(e) => { 
                if (f.reason !== reason) e.currentTarget.style.background = darkMode ? '#1e293b' : '#ffffff'; 
            }}
          >
            <span>{polyglot.t(`filters.reason.${reason}`)}</span>
          </Button>
        ))}
      </div>
      
      {filterCount > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, margin: 0, width: '100%', justifyContent: isSidebar ? 'flex-start' : 'center', marginTop: 4 }}>
          <Button
            style={{
                ...buttonStyle(false, true),
                fontSize: '0.7rem',
                opacity: 0.8,
                border: 'none',
                background: 'transparent',
                textDecoration: 'underline'
            }}
            onClick={() => onChange({ market: null, signal: null, reason: null })}
            onMouseEnter={(e) => { e.currentTarget.style.opacity = '1'; }}
            onMouseLeave={(e) => { e.currentTarget.style.opacity = '0.8'; }}
          >
            <span>{polyglot.t('filters.clear')}</span>
          </Button>
        </div>
      )}

    </div>
  );
}

export default SignalFilters;
