import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'react-toastify';
import { useLocation, useNavigate } from 'react-router-dom';
import { Container, Card, Button } from 'react-bootstrap';
import { isDarkModeEnabled } from '../settings';
import { setPushNotification, getNotificationConfig } from '../api';
import { registerForPushNotifications } from '../notification';
import BackButton from '../components/BackButton';
import CryptoLogo from '../components/CryptoLogo';
import { Capacitor } from '@capacitor/core';
import { PushNotifications } from '@capacitor/push-notifications';

const notificationTypes = [
  { key: 'trend' },
  { key: 'reversal' },
  { key: 'spike' },
];

const NotificationConfig = ({ polyglot }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [darkMode, setDarkMode] = useState(isDarkModeEnabled());
  const { crypto, timeframe, market } = location.state || {};
  const [selectedTypes, setSelectedTypes] = useState([]);
  const [initialTypes, setInitialTypes] = useState([]);
  const toastIdRef = useRef(null);

  // Listen for dark mode changes using matchMedia
  useEffect(() => {
    const darkModeMedia = window.matchMedia('(prefers-color-scheme: dark)');
    const handleDarkModeChange = () => {
      setDarkMode(isDarkModeEnabled());
    };
    darkModeMedia.addEventListener('change', handleDarkModeChange);
    return () => {
      darkModeMedia.removeEventListener('change', handleDarkModeChange);
    };
  }, []);
  // On mount, fetch current notification config for this crypto
  useEffect(() => {
    const fetchConfig = async () => {
      try {
        const token = localStorage.getItem('jerryToken');
        const config = await getNotificationConfig(token, crypto, market, timeframe);
        // config is expected to have notify_trend, notify_spike, notify_reversal (booleans)
        const initialTypes = [];
        if (config.notify_trend) initialTypes.push('trend');
        if (config.notify_spike) initialTypes.push('spike');
        if (config.notify_reversal) initialTypes.push('reversal');
        setSelectedTypes(initialTypes);
        setInitialTypes(initialTypes);
      } catch (err) {
        // Optionally handle error (e.g., show a message)
      }
    };
    fetchConfig();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [crypto, market, timeframe]);
  const [submitting, setSubmitting] = useState(false);

  if (!crypto || !timeframe || !market) {
    navigate(-1);
    return null;
  }

  const handleTypeChange = (type) => {
    setSelectedTypes((prev) =>
      prev.includes(type)
        ? prev.filter((t) => t !== type)
        : [...prev, type]
    );
  };

  const handleSubmit = async () => {
    setSubmitting(true);
    try {
      console.log('Submitting notification config for:', JSON.stringify({ crypto, market, timeframe, selectedTypes }));

      const token = localStorage.getItem('jerryToken');

      await registerForPushNotifications(token, null);

      // Set each notify_* variable based on selection
      const notify_trend = selectedTypes.includes('trend');
      const notify_spike = selectedTypes.includes('spike');
      const notify_reversal = selectedTypes.includes('reversal');

      await setPushNotification(token, {
        pair_name: crypto,
        market_name: market,
        timeframe,
        notify_trend,
        notify_spike,
        notify_reversal
      });

      setSubmitting(false);
      navigate(-1);
    } catch (err) {
      console.error('Error setting notification config buu:', err);

      if (err instanceof Error) {
        console.error('Error setting notification config:', err.message);
        console.error('Stack trace:', err.stack);
      }

      // If it’s a network response error (e.g. from fetch)
      if (err.response) {
        console.error('Backend responded with status:', err.response.status);
        console.error('Response body:', await err.response.text?.());
      }

      setSubmitting(false);

      if (
        err && (
          (err.message && err.message.toLowerCase().includes('permission')) ||
          (typeof Notification !== 'undefined' && Notification.permission === 'denied')
        )
      ) {
        toast.error(
          'Notification permission denied. Please enable notifications in your settings.',
          { theme: darkMode ? 'dark' : 'light' }
        );
      } else {
        navigate('/paywall');
      }
    }
  };

  return (
    <Container
      className={`mt-4${darkMode ? ' crypto-details-dark' : ''}`}
      style={darkMode ? {
        background: '#101624',
        color: '#e0e6f0',
        borderRadius: '12px',
        boxShadow: '0 2px 16px 0 rgba(16,22,36,0.4)',
        minHeight: '100vh',
        maxWidth: '1200px',
        margin: '0 auto',
        paddingBottom: '2rem',
        width: '100%',
      } : {
        background: '#fff',
        color: '#222',
        borderRadius: '12px',
        minHeight: '100vh',
        maxWidth: '1200px',
        margin: '0 auto',
        paddingBottom: '2rem',
        width: '100%',
      }}
    >
      <div className="mb-3" style={{ display: 'flex', alignItems: 'center', maxWidth: 900, margin: '0 auto', minHeight: 48 }}>
        <BackButton polyglot={polyglot} />
      </div>
      <Card
        className="mx-auto mb-4"
        style={darkMode ? {
          background: '#18213a',
          color: '#e0e6f0',
          border: '1px solid #22304a',
          maxWidth: 900,
          width: '100%',
          margin: '0 auto',
        } : {
          background: '#fff',
          color: '#222',
          border: '1px solid #e0e6f0',
          maxWidth: 900,
          width: '100%',
          margin: '0 auto',
        }}
      >
        <Card.Body>
          <div className="d-flex align-items-center mb-3">
            <div style={{ marginRight: 16 }}>
              <CryptoLogo cryptoPairName={crypto} />
            </div>
            <div>
              <div style={{ fontWeight: 700, fontSize: '1.2rem' }}>{crypto}</div>
              <div style={{ fontSize: '1rem', color: darkMode ? '#b0b8c1' : '#666' }}>{polyglot.t(`markets.${market}`)} / {polyglot.t(`timeframes.${timeframe}`)}</div>
            </div>
          </div>
          <div
            className="mb-3"
            style={{
              fontWeight: 500,
              fontSize: '0.98rem',
              color: darkMode ? '#b0b8c1' : '#888',
              letterSpacing: 0.1,
            }}
          >
            {polyglot.t('notification.selectTypes')}
          </div>
          <div className="d-flex justify-content-between gap-3 mb-4 flex-wrap">
            {notificationTypes.map((type) => {
              const checked = selectedTypes.includes(type.key);
              return (
                <Button
                  key={type.key}
                  onClick={() => handleTypeChange(type.key)}
                  style={{
                    minWidth: 120,
                    fontWeight: 600,
                    fontSize: '1.08rem',
                    borderRadius: 12,
                    boxShadow: checked ? (darkMode ? '0 0 0 2px #4fd1c5' : '0 0 0 2px #007bff') : 'none',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    gap: 8,
                    padding: '10px 18px',
                    marginBottom: 8,
                    transition: 'all 0.15s',
                    background: checked
                      ? (darkMode ? '#4fd1c5' : '#007bff')
                      : (darkMode ? '#18213a' : '#fff'),
                    color: checked
                      ? (darkMode ? '#101624' : '#fff')
                      : (darkMode ? '#e0e6f0' : '#222'),
                    border: checked
                      ? (darkMode ? '2px solid #4fd1c5' : '2px solid #007bff')
                      : (darkMode ? '2px solid #3a4252' : '2px solid #ccc'),
                  }}
                  aria-pressed={checked}
                >
                  <span style={{ fontSize: '1.25em' }}>{polyglot.t(`signal.reason.${type.key}.buy`)}</span>
                  <span>{polyglot.t(`signal.reason.${type.key}.label`)}</span>
                </Button>
              );
            })}
          </div>
          <Button
            variant={darkMode ? 'info' : 'primary'}
            style={{ fontWeight: 600, width: '100%' }}
            disabled={
              submitting ||
              (selectedTypes.length === initialTypes.length &&
                selectedTypes.every((t) => initialTypes.includes(t)) &&
                initialTypes.every((t) => selectedTypes.includes(t))
              )
            }
            onClick={handleSubmit}
          >
            {submitting ? polyglot.t('label.loading') : polyglot.t('label.confirm')}
          </Button>
        </Card.Body>
      </Card>
    </Container>
  );
};

export default NotificationConfig;
