import React, { useState, useEffect, useCallback } from 'react';
import { Button, Modal, Spinner } from 'react-bootstrap';
import { FaTelegramPlane, FaCheckCircle } from 'react-icons/fa';
import { getTelegramLinkCode, getTelegramStatus, disconnectTelegram } from '../api';
import { getJerryToken } from '../util';

const TelegramConfig = ({ polyglot, darkMode }) => {
    const [status, setStatus] = useState(null); // 'connected', 'not_connected'
    const [showModal, setShowModal] = useState(false);
    const [linkCode, setLinkCode] = useState(null);
    const [loading, setLoading] = useState(true);
    const [linking, setLinking] = useState(false);
    const token = getJerryToken();

    const fetchStatus = useCallback(async () => {
        try {
            const data = await getTelegramStatus(token);
            setStatus(data.connected ? 'connected' : 'not_connected');
        } catch (error) {
            console.error("Error fetching telegram status", error);
        } finally {
            setLoading(false);
        }
    }, [token]);

    useEffect(() => {
        fetchStatus();
    }, [fetchStatus]);

    const handleConnect = async () => {
        setLinking(true);
        setShowModal(true);
        try {
            const data = await getTelegramLinkCode(token);
            setLinkCode(data.code);
            // Polling is handled by useEffect when modal is open
        } catch (error) {
            console.error("Error getting link code", error);
            setLinking(false);
        }
    };

    // Polling logic when modal is open and linking
    useEffect(() => {
        let interval;
        if (showModal && status !== 'connected') {
            interval = setInterval(async () => {
                try {
                    const data = await getTelegramStatus(token);
                    if (data.connected) {
                        setStatus('connected');
                        setLinking(false);
                        clearInterval(interval);
                        // Auto close modal after success
                        setTimeout(() => setShowModal(false), 2500);
                    }
                } catch (error) {
                    console.error("Polling error", error);
                }
            }, 3000);
        }
        return () => {
            if (interval) clearInterval(interval);
        };
    }, [showModal, status, token]);

    const handleDisconnect = async () => {
        if (!window.confirm("Are you sure you want to disconnect Telegram?")) return;
        try {
            await disconnectTelegram(token);
            setStatus('not_connected');
        } catch (error) {
            console.error("Error disconnecting telegram", error);
        }
    };

    if (loading) return (
        <div className="text-center p-3">
            <Spinner animation="border" size="sm" variant={darkMode ? "light" : "primary"} />
        </div>
    );

    return (
        <div style={{
            background: darkMode ? '#18213a' : '#f8fafc',
            borderRadius: '16px',
            padding: '24px',
            border: darkMode ? '1px solid rgba(44, 62, 80, 0.6)' : '1px solid #e2e8f0',
        }}>
            <h6 style={{ fontWeight: 700, marginBottom: '20px', opacity: 0.8, textTransform: 'uppercase', fontSize: '0.75rem' }}>
                {polyglot.t("telegram.title")}
            </h6>
            
            <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
                <div style={{
                    width: '48px',
                    height: '48px',
                    borderRadius: '12px',
                    background: '#0088cc',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: 'white',
                    fontSize: '1.5rem',
                    boxShadow: '0 4px 12px rgba(0, 136, 204, 0.3)'
                }}>
                    <FaTelegramPlane />
                </div>
                <div style={{ flex: 1 }}>
                    <div style={{ fontWeight: 600, fontSize: '0.95rem' }}>
                        {status === 'connected' ? polyglot.t("telegram.connected") : polyglot.t("telegram.notConnected")}
                    </div>
                    <div style={{ fontSize: '0.8rem', opacity: 0.6 }}>
                        {polyglot.t("telegram.description")}
                    </div>
                </div>
            </div>

            <div style={{ marginTop: '20px' }}>
                {status === 'connected' ? (
                    <Button 
                        variant="outline-danger" 
                        size="sm" 
                        onClick={handleDisconnect}
                        style={{ borderRadius: '10px', width: '100%', fontWeight: 600 }}
                    >
                        {polyglot.t("telegram.disconnect")}
                    </Button>
                ) : (
                    <Button 
                        variant="primary" 
                        size="sm" 
                        onClick={handleConnect}
                        style={{ 
                            borderRadius: '10px', 
                            width: '100%', 
                            background: '#0088cc', 
                            border: 'none',
                            fontWeight: 700,
                            padding: '10px'
                        }}
                    >
                        {polyglot.t("telegram.connect")}
                    </Button>
                )}
            </div>

            <Modal show={showModal} onHide={() => setShowModal(false)} centered>
                <Modal.Header closeButton style={darkMode ? { background: '#0b101a', color: '#e0e6f0', borderBottom: '1px solid rgba(44, 62, 80, 0.6)' } : {}}>
                    <Modal.Title style={{ fontSize: '1.2rem', fontWeight: 700 }}>
                        {polyglot.t("telegram.modal.title")}
                    </Modal.Title>
                </Modal.Header>
                <Modal.Body style={darkMode ? { background: '#18213a', color: '#e0e6f0', padding: '30px' } : { padding: '30px' }}>
                    {status === 'connected' ? (
                        <div className="text-center py-4">
                            <FaCheckCircle style={{ fontSize: '4.5rem', color: '#4fd1c5', marginBottom: '20px' }} />
                            <h5 style={{ fontWeight: 700 }}>{polyglot.t("telegram.modal.success")}</h5>
                        </div>
                    ) : (
                        <div>
                            <p style={{ marginBottom: '15px', fontSize: '0.95rem' }}>{polyglot.t("telegram.modal.step1")}</p>
                            <p style={{ marginBottom: '10px', fontSize: '0.95rem' }}>{polyglot.t("telegram.modal.step2")}</p>
                            <div style={{
                                background: darkMode ? 'rgba(0,0,0,0.3)' : '#f1f5f9',
                                padding: '20px',
                                borderRadius: '12px',
                                textAlign: 'center',
                                fontSize: '1.8rem',
                                fontWeight: 800,
                                letterSpacing: '6px',
                                color: '#0088cc',
                                marginBottom: '24px',
                                border: '2px dashed rgba(0, 136, 204, 0.5)',
                                fontFamily: 'monospace'
                            }}>
                                {linkCode || <Spinner animation="border" size="sm" />}
                            </div>
                            <p style={{ marginBottom: '15px', fontSize: '0.95rem' }}>{polyglot.t("telegram.modal.step3")}</p>
                            <Button 
                                href={`https://t.me/JerrySignalsBot?start=${linkCode}`} 
                                target="_blank"
                                style={{ 
                                    width: '100%', 
                                    background: '#0088cc', 
                                    border: 'none', 
                                    padding: '14px',
                                    fontWeight: 700,
                                    borderRadius: '12px',
                                    marginBottom: '24px',
                                    boxShadow: '0 4px 12px rgba(0, 136, 204, 0.2)'
                                }}
                            >
                                <FaTelegramPlane style={{ marginRight: '10px' }} />
                                {polyglot.t("telegram.modal.openBot")}
                            </Button>
                            
                            <div className="text-center" style={{ opacity: 0.6, fontSize: '0.85rem' }}>
                                <Spinner animation="border" size="sm" style={{ marginRight: '10px' }} />
                                {polyglot.t("telegram.modal.waiting")}
                            </div>
                        </div>
                    )}
                </Modal.Body>
            </Modal>
        </div>
    );
};

export default TelegramConfig;
