import React from 'react';
import { Button } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { isDarkModeEnabled } from '../settings';

const BackButton = ({ polyglot }) => {
    const navigate = useNavigate();
    const darkMode = isDarkModeEnabled();
    const darkStyle = {
        background: '#22304a',
        color: '#e0e6f0',
        border: 'none',
        borderRadius: '6px',
        fontWeight: 600,
        boxShadow: '0 2px 8px 0 rgba(16,22,36,0.18)',
    };
    return (
        <Button
          variant={darkMode ? undefined : 'secondary'}
          onClick={() => navigate(-1)}
          style={darkMode ? darkStyle : {}}
        >
          {polyglot.t('label.goBack')}
        </Button>
    );
};

export default BackButton;
