import React from 'react';
import { Container, Button } from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { isDarkModeEnabled } from '../settings';
import BackButton from '../components/BackButton';

const SubscriptionCancel = ({ polyglot }) => {
    const navigate = useNavigate();
    const darkMode = isDarkModeEnabled();

    const handleReturn = () => {
        navigate('/paywall');
    };

    return (
        <Container
            className="d-flex align-items-center justify-content-center"
            style={{ minHeight: '80vh' }}
        >
            <div className="text-center p-5" style={{
                background: darkMode ? '#18213a' : '#fff',
                borderRadius: '24px',
                border: darkMode ? '1px solid #22304a' : '1px solid #eef2f7',
                boxShadow: darkMode ? '0 20px 40px rgba(0,0,0,0.4)' : '0 20px 40px rgba(0,0,0,0.05)',
                maxWidth: '500px',
                width: '100%'
            }}>
                <div className="mb-4">
                    <BackButton polyglot={polyglot} />
                </div>

                <div style={{ fontSize: '4rem', marginBottom: '1.5rem' }}>👋</div>

                <h2 className="mb-4" style={{ fontWeight: 700 }}>
                    Manage Subscription
                </h2>

                <p style={{
                    color: darkMode ? '#8fa3c8' : '#666',
                    fontSize: '1.1rem',
                    lineHeight: '1.6',
                    marginBottom: '2rem'
                }}>
                    Currently, the self-service cancellation portal is under maintenance.
                    To manage or cancel your active subscription, please contact our support team.
                </p>

                <Button
                    variant="primary"
                    onClick={handleReturn}
                    style={{
                        borderRadius: '8px',
                        padding: '0.75rem 2rem',
                        fontWeight: 600,
                        width: '100%'
                    }}
                >
                    {polyglot.t('subscriptionCancel.returnToPlans')}
                </Button>
            </div>
        </Container>
    );
};

export default SubscriptionCancel;
