import React, { useState } from 'react';
import {
    PaymentElement,
    useStripe,
    useElements
} from '@stripe/react-stripe-js';
import { Button, Alert, Spinner } from 'react-bootstrap';

const StripePaymentForm = ({ planKey, planPrice, polyglot, darkMode, onSuccess }) => {
    const stripe = useStripe();
    const elements = useElements();

    const [message, setMessage] = useState(null);
    const [isLoading, setIsLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();

        if (!stripe || !elements) {
            // Stripe.js has not yet loaded.
            // Make sure to disable form submission until Stripe.js has loaded.
            return;
        }

        setIsLoading(true);

        const { error } = await stripe.confirmPayment({
            elements,
            confirmParams: {
                // Make sure to change this to your payment completion page
                return_url: window.location.origin + "/#/payment/success",
            },
        });

        // This point will only be reached if there is an immediate error when
        // confirming the payment. Otherwise, your customer will be redirected to
        // your `return_url`. For some payment methods like iDEAL, your customer will
        // be redirected to an intermediate site first to authorize the payment, then
        // redirected to the `return_url`.
        if (error.type === "card_error" || error.type === "validation_error") {
            setMessage(error.message);
        } else {
            setMessage("An unexpected error occurred.");
        }

        setIsLoading(false);
    };

    const paymentElementOptions = {
        layout: "tabs",
        theme: darkMode ? 'night' : 'stripe',
    };

    return (
        <form id="payment-form" onSubmit={handleSubmit}>
            <PaymentElement id="payment-element" options={paymentElementOptions} />
            <div className="d-grid gap-2 mt-4">
                <Button
                    variant={planKey === 'elite' ? 'warning' : planKey === 'pro' ? 'primary' : 'success'}
                    size="lg"
                    disabled={isLoading || !stripe || !elements}
                    type="submit"
                    id="submit"
                    style={{
                        fontWeight: 600,
                        fontSize: '1.1rem',
                        padding: '1rem',
                        borderRadius: '8px'
                    }}
                >
                    {isLoading ? (
                        <Spinner animation="border" size="sm" />
                    ) : (
                        `${polyglot.t('payment.actions.payNow')} ${planPrice} / ${polyglot.t('payment.planSummary.monthly')}`
                    )}
                </Button>
            </div>
            {/* Show any error or success messages */}
            {message && (
                <Alert variant="danger" className="mt-3">
                    {message}
                </Alert>
            )}
        </form>
    );
};

export default StripePaymentForm;
