import { useState, useEffect } from "react";
import { Card, Container, Spinner, Button, Modal } from "react-bootstrap";
import { getUserData } from "../jerryTokenUtil";
import BackButton from "../components/BackButton";
import { getProfile } from "../sessionCache";
import { getJerryToken } from "../util";
import { Switch, FormControlLabel } from '@mui/material';
import { isDarkModeEnabled, saveDarkMode } from "../settings";
import { useNavigate } from "react-router-dom";
import { useAuth0 } from "@auth0/auth0-react";

const Profile = ({ polyglot }) => {
    const [user, setUser] = useState(null);
    const token = getJerryToken();
    const userTokenData = getUserData();
    const [isDarkMode, setIsDarkMode] = useState(isDarkModeEnabled());
    const navigate = useNavigate();
    const { logout } = useAuth0();
    const [showConfirmLogout, setShowConfirmLogout] = useState(false);
    const handleLogout = () => {
        localStorage.removeItem('jerryToken');
        localStorage.removeItem('auth0Token');
        
        logout({
            returnTo: window.location.origin,
        });
    };

    // Scroll to top on mount
    useEffect(() => {
        window.scrollTo({ top: 0, behavior: 'auto' });
    }, []);

    const handleDarkModeToggle = () => {
        setIsDarkMode((prev) => !prev);
        saveDarkMode(!isDarkMode);
      };

    const handleUpgradeClick = () => {
        navigate('/paywall');
    };

    const formatMembershipDuration = (dateString) => {
        const givenDate = new Date(dateString);
        const currentDate = new Date();
    
        let years = currentDate.getFullYear() - givenDate.getFullYear();
        let months = currentDate.getMonth() - givenDate.getMonth();
        let days = currentDate.getDate() - givenDate.getDate();
    
        if (days < 0) {
            months -= 1;
            const previousMonth = new Date(currentDate.getFullYear(), currentDate.getMonth(), 0);
            days += previousMonth.getDate();
        }
    
        if (months < 0) {
            years -= 1;
            months += 12;
        }
    
        return { years, months, days };
    };
    

    useEffect(() => {
        const fetchProfile = async () => {
            try {
                const profileData = await getProfile(token);
                setUser(profileData);
            } catch (error) {
                console.error("Error fetching profile:", error);
            }
        };

        fetchProfile();
    }, [token]);

    if (!user) {
        return (
            <Container className="mt-4 text-center">
                <Spinner animation="border" role="status">
                    <span className="visually-hidden">{polyglot.t('label.loading')}</span>
                </Spinner>
            </Container>
        );
    }

    const membershipDuration = formatMembershipDuration(user.created_at);

    let translationKey = "profile.memberAge.period.d"; // Default: Only days
    if (membershipDuration.years > 0) {
        translationKey = "profile.memberAge.period.ymd"; // Use years, months, and days
    } else if (membershipDuration.months > 0) {
        translationKey = "profile.memberAge.period.md"; // Use months and days
    }

    return (
        <Container
            className={`profile-container${isDarkMode ? ' profile-dark' : ''}`}
            style={{
                ...(isDarkMode ? {
                    background: '#101624',
                    color: '#e0e6f0',
                    borderRadius: '12px',
                    boxShadow: '0 2px 16px 0 rgba(16,22,36,0.4)',
                    minHeight: 'calc(100vh - 120px)',
                    paddingBottom: '2rem'
                } : { color: '#222', minHeight: 'calc(100vh - 120px)', paddingBottom: '2rem' }),
                maxWidth: '1400px',
                margin: '1.5rem auto',
                padding: '0 20px',
                border: 'none'
            }}
        >
            <div className="mb-4 pt-2">
                <BackButton polyglot={polyglot} />
            </div>

            <div className="row g-4">
                {/* SIDEBAR: User Info & Actions */}
                <aside className="col-md-4 col-lg-3">
                    <div style={{
                        position: 'sticky',
                        top: '20px',
                        display: 'flex',
                        flexDirection: 'column',
                        gap: '20px'
                    }}>
                        {/* Profile Info Card */}
                        <div style={{
                            background: isDarkMode ? '#18213a' : '#f8fafc',
                            borderRadius: '20px',
                            padding: '30px 24px',
                            border: isDarkMode ? '1px solid rgba(44, 62, 80, 0.6)' : '1px solid #e2e8f0',
                            textAlign: 'center'
                        }}>
                            <img
                                src={userTokenData.picture}
                                alt="Profile"
                                className="rounded-circle mb-3"
                                style={{ 
                                    width: "120px", 
                                    height: "120px", 
                                    objectFit: "cover",
                                    border: isDarkMode ? '4px solid #22304a' : '4px solid #fff',
                                    boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
                                }}
                            />
                            <h5 style={{ fontWeight: 800, marginBottom: '4px' }}>{user.name}</h5>
                            <p style={{ fontSize: '0.85rem', opacity: 0.6, marginBottom: '20px' }}>{user.email}</p>
                            
                            <div style={{ 
                                background: isDarkMode ? 'rgba(34, 48, 74, 0.5)' : '#fff',
                                borderRadius: '12px',
                                padding: '12px',
                                fontSize: '0.85rem',
                                border: isDarkMode ? '1px solid rgba(44, 62, 80, 0.4)' : '1px solid #e2e8f0',
                                marginBottom: '24px'
                            }}>
                                <span style={{ opacity: 0.7 }}>{polyglot.t("profile.memberAge.text")}</span>
                                <div style={{ fontWeight: 600, marginTop: '4px' }}>
                                    {polyglot.t(translationKey, {
                                        years: membershipDuration.years,
                                        months: membershipDuration.months,
                                        days: membershipDuration.days,
                                    })}
                                </div>
                            </div>

                            <Button
                                variant="danger"
                                style={{ 
                                    width: '100%',
                                    borderRadius: '12px',
                                    padding: '12px',
                                    fontWeight: 600,
                                    fontSize: '0.9rem',
                                    background: '#e57373',
                                    border: 'none',
                                    transition: 'all 0.2s'
                                }}
                                onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-2px)'; }}
                                onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0)'; }}
                                onClick={() => setShowConfirmLogout(true)}
                            >
                                {polyglot.t('logout.button')}
                            </Button>
                        </div>
                    </div>
                </aside>

                {/* MAIN CONTENT: Plan Details */}
                <main className="col-md-8 col-lg-9">
                    <div style={{
                        background: isDarkMode ? 'rgba(24, 33, 58, 0.2)' : '#f8fafc',
                        border: isDarkMode ? '1px solid rgba(44, 62, 80, 0.4)' : '1px solid #e2e8f0',
                        borderRadius: '20px',
                        padding: '32px',
                        minHeight: '440px'
                    }}>
                        <h6 style={{ fontWeight: 700, marginBottom: '32px', opacity: 0.8, textTransform: 'uppercase', fontSize: '0.75rem' }}>
                            {polyglot.t("profile.plan.title")}
                        </h6>

                        {user.plan_name.toLowerCase() === 'elite' ? (
                            <div style={{ maxWidth: '600px' }}>
                                <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: '24px' }}>
                                    <div style={{ 
                                        background: '#ffc107',
                                        width: '48px',
                                        height: '48px',
                                        borderRadius: '12px',
                                        display: 'flex',
                                        alignItems: 'center',
                                        justifyContent: 'center',
                                        fontSize: '1.5rem'
                                    }}>
                                        🏆
                                    </div>
                                    <div>
                                        <div style={{ fontSize: '1.5rem', fontWeight: 800 }}>
                                            {polyglot.t(`plan.${user.plan_name.toLowerCase()}`)}
                                        </div>
                                        <div style={{
                                            backgroundColor: 'rgba(255, 193, 7, 0.1)',
                                            color: '#ffc107',
                                            padding: '2px 10px',
                                            borderRadius: '6px',
                                            fontSize: '0.7rem',
                                            fontWeight: 700,
                                            display: 'inline-block',
                                            marginTop: '4px'
                                        }}>
                                            {polyglot.t("profile.plan.elite.badge")}
                                        </div>
                                    </div>
                                </div>
                                
                                <p style={{ fontSize: '1.1rem', marginBottom: '24px', opacity: 0.9 }}>
                                    {polyglot.t("profile.plan.elite.subtitle")}
                                </p>

                                <div style={{ 
                                    padding: '24px',
                                    backgroundColor: isDarkMode ? '#18213a' : '#fff',
                                    borderRadius: '16px',
                                    border: `1px solid ${isDarkMode ? '#22304a' : '#e2e8f0'}`,
                                    lineHeight: '1.6',
                                    boxShadow: '0 4px 12px rgba(0,0,0,0.02)'
                                }}>
                                    {polyglot.t("profile.plan.elite.message")}
                                </div>
                            </div>
                        ) : (
                            <div style={{ maxWidth: '500px' }}>
                                <div style={{ 
                                    display: 'flex', 
                                    justifyContent: 'space-between',
                                    alignItems: 'center',
                                    marginBottom: '32px',
                                    padding: '24px',
                                    background: isDarkMode ? '#18213a' : '#fff',
                                    borderRadius: '16px',
                                    border: isDarkMode ? '1px solid #22304a' : '1px solid #e2e8f0'
                                }}>
                                    <div>
                                        <div style={{ opacity: 0.6, fontSize: '0.75rem', textTransform: 'uppercase', fontWeight: 700, marginBottom: '4px' }}>Active Plan</div>
                                        <div style={{ fontSize: '1.4rem', fontWeight: 800 }}>
                                            {polyglot.t(`plan.${user.plan_name.toLowerCase()}`)}
                                        </div>
                                    </div>
                                    <Button 
                                        variant="primary"
                                        onClick={handleUpgradeClick}
                                        style={{
                                            borderRadius: '10px',
                                            padding: '10px 20px',
                                            fontWeight: 700,
                                            background: '#2563eb',
                                            border: 'none'
                                        }}
                                    >
                                        {polyglot.t("profile.plan.upgradeLink")}
                                    </Button>
                                </div>
                                <p style={{ fontSize: '0.95rem', opacity: 0.8, marginLeft: '4px' }}>
                                    {polyglot.t("profile.plan.upgradeText")}
                                </p>
                            </div>
                        )}
                    </div>
                </main>
            </div>

            {/* Confirmation Modal */}
            <Modal show={showConfirmLogout} onHide={() => setShowConfirmLogout(false)} centered>
                <Modal.Header closeButton style={isDarkMode ? { background: '#0b101a', color: '#e0e6f0', borderBottom: '1px solid rgba(44, 62, 80, 0.6)' } : {}}>
                    <Modal.Title style={isDarkMode ? { color: '#e0e6f0' } : {}}>{polyglot.t('logout.confirmLogoutTitle')}</Modal.Title>
                </Modal.Header>
                <Modal.Body style={isDarkMode ? { background: '#18213a', color: '#e0e6f0' } : {}}>
                    {polyglot.t('logout.confirmLogoutMessage')}
                </Modal.Body>
                <Modal.Footer style={isDarkMode ? { background: '#0b101a', borderTop: '1px solid rgba(44, 62, 80, 0.6)' } : {}}>
                    <Button variant={isDarkMode ? undefined : 'secondary'} style={isDarkMode ? { background: '#22304a', color: '#e0e6f0', border: 'none' } : {}} onClick={() => setShowConfirmLogout(false)}>
                        {polyglot.t('logout.cancel')}
                    </Button>
                    <Button variant={isDarkMode ? undefined : 'danger'} style={isDarkMode ? { background: '#e57373', color: '#e0e6f0', border: 'none' } : {}} onClick={handleLogout}>
                        {polyglot.t('logout.confirm')}
                    </Button>
                </Modal.Footer>
            </Modal>
        </Container>
    );
};

export default Profile;
