import React, { useState, useEffect } from 'react';
import SignalFilters from '../components/SignalFilters';
import { Container } from 'react-bootstrap';
import { toast } from 'react-toastify';
import SignalData from '../components/SignalData';
import useSessionExpired from '../hooks/useSessionExpired';
import { useLocation, useNavigate } from 'react-router-dom';
import './MainPage.css'; // Import the CSS file
import { isDarkModeEnabled } from '../settings'; // Import the dark mode utility
import { isShowFiltersEnabled, saveShowFilters, getFilterValue, saveFilterValue } from '../settings';

const MainPage = ({ polyglot, setRefreshKey }) => {
    const navigate = useNavigate();
    // Collapsible filter state
    const [showFilters, setShowFilters] = useState(isShowFiltersEnabled());
    // --- FILTER STATE ---
    const [filters, setFilters] = useState({ market: null, signal: null, reason: null });
    // Filter count state
    const [filterCount, setFilterCount] = useState(0);
    // Load individual filters from localStorage on mount
    useEffect(() => {
        const initialFilters = {
            market: getFilterValue('market'),
            signal: getFilterValue('signal'),
            reason: getFilterValue('reason'),
        };
        setFilters(initialFilters);
        // Set initial filter count based on loaded filters
        const initialCount = [initialFilters.market, initialFilters.signal, initialFilters.reason].filter(Boolean).length;
        setFilterCount(initialCount);
    }, []);
    // Persist each filter to localStorage when changed
    useEffect(() => {
        saveFilterValue('market', filters.market);
        saveFilterValue('signal', filters.signal);
        saveFilterValue('reason', filters.reason);
    }, [filters]);
    const [lastUpdated, setLastUpdated] = useState(null);
    const [refreshSignal, setRefreshSignal] = useState(0); // Use a counter to guarantee uniqueness
    const [loading, setLoading] = useState(true); // Default to true for initial load
    // const [alertMessage, setAlertMessage] = useState(null); // Track alert message
    const location = useLocation();
    const darkMode = isDarkModeEnabled(); // Check if dark mode is enabled

    // Scroll to top on mount
    useEffect(() => {
        window.scrollTo({ top: 0, behavior: 'auto' });
    }, []);

    useEffect(() => {
        if (location.state?.alert) {
            toast.warn(location.state.alert, {
                theme: darkMode ? 'dark' : 'light',
            });
            window.history.replaceState({}, document.title); // Clear the state from the history
            triggerRefresh();
        }
    }, [location.state, darkMode]);

    const handleDataLoaded = (timestamp) => {
        setLastUpdated(timestamp);
        setLoading(false); // Stop showing "Loading..." once data is loaded
    };

    const triggerRefresh = () => {
        setLoading(true); // Show "Loading..." immediately
        setRefreshSignal((prev) => prev + 1); // Increment refreshSignal to trigger refresh
    };

    const SessionExpiredModal = useSessionExpired(polyglot);

    // Automatically refresh every minute
    useEffect(() => {
        const interval = setInterval(() => {
            triggerRefresh();
        }, 60000);

        return () => clearInterval(interval);
    }, []); // Run only once on mount

    return (
        <Container
            className={`main-container${darkMode ? ' dark-mode' : ''}`}
            style={{
                ...(darkMode ? {
                    background: '#101624', // blueish, near-black
                    color: '#e0e6f0',
                    minHeight: 'calc(100vh - 120px)',
                    borderRadius: '12px',
                    boxShadow: '0 2px 16px 0 rgba(10,22,36,0.4)'
                } : {}),
                maxWidth: '1400px',
                margin: '1.5rem auto',
                padding: '0 20px',
                border: 'none'
            }}
        >
            <div className="row g-4">
                {/* SIDEBAR: Desktop only (md and up) */}
                <aside className="col-md-3 d-none d-md-block">
                    <div style={{
                        position: 'sticky',
                        top: '20px',
                        display: 'flex',
                        flexDirection: 'column',
                        gap: '20px'
                    }}>
                        {/* Desktop Actions */}
                        <div style={{
                            background: darkMode ? '#18213a' : '#f8fafc',
                            borderRadius: '16px',
                            padding: '20px',
                            border: darkMode ? '1px solid rgba(44, 62, 80, 0.6)' : '1px solid #e2e8f0',
                            display: 'flex',
                            flexDirection: 'column',
                            gap: '12px'
                        }}>
                            <div style={{ opacity: 0.5, fontSize: '0.75rem', fontWeight: 600, marginBottom: '4px', textTransform: 'uppercase' }}>
                                {loading ? polyglot.t('label.loading') : `${polyglot.t('label.lastUpdated')}: ${lastUpdated || polyglot.t('notifications.none')}`}
                            </div>
                            <button
                                onClick={triggerRefresh}
                                style={{
                                    background: darkMode ? '#253250' : '#ffffff',
                                    color: darkMode ? '#e0e6f0' : '#475569',
                                    border: darkMode ? '1px solid rgba(44, 62, 80, 0.6)' : '1px solid #cbd5e1',
                                    borderRadius: '12px',
                                    padding: '12px',
                                    fontWeight: 600,
                                    fontSize: '0.9rem',
                                    cursor: 'pointer',
                                    transition: 'all 0.2s ease',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    gap: '8px'
                                }}
                                onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-2px)'; }}
                                onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0)'; }}
                            >
                                <span>↻</span> {polyglot.t('label.refresh')}
                            </button>
                            <button
                                onClick={() => navigate('/add-crypto')}
                                style={{
                                    background: darkMode ? '#3b82f6' : '#2563eb',
                                    color: '#ffffff',
                                    border: 'none',
                                    borderRadius: '12px',
                                    padding: '12px',
                                    fontWeight: 600,
                                    fontSize: '0.9rem',
                                    cursor: 'pointer',
                                    transition: 'all 0.2s ease',
                                    display: 'flex',
                                    alignItems: 'center',
                                    justifyContent: 'center',
                                    gap: '8px'
                                }}
                                onMouseEnter={(e) => { e.currentTarget.style.transform = 'translateY(-2px)'; }}
                                onMouseLeave={(e) => { e.currentTarget.style.transform = 'translateY(0)'; }}
                            >
                                {polyglot.t('signal.addCrypto')}
                            </button>
                        </div>

                        {/* Desktop Filters */}
                        <div style={{
                            background: darkMode ? '#141c2f' : '#f1f5f9',
                            borderRadius: '16px',
                            padding: '20px',
                            border: darkMode ? '1px solid rgba(44, 62, 80, 0.4)' : '1px solid #e2e8f0',
                        }}>
                            <h6 style={{ fontWeight: 700, marginBottom: '16px', opacity: 0.8 }}>{polyglot.t('filters.title') || 'Filters'}</h6>
                            <SignalFilters
                                filters={filters}
                                onChange={setFilters}
                                polyglot={polyglot}
                                darkMode={darkMode}
                                availableMarkets={['USD_M_FUTURES', 'SPOT']}
                                availableSignals={['buy', 'sell']}
                                availableReasons={['spike', 'reversal', 'trend']}
                                onCountChange={setFilterCount}
                                isSidebar={true}
                            />
                        </div>
                    </div>
                </aside>

                {/* MAIN CONTENT AREA */}
                <main className="col-12 col-md-9">
                    {/* Mobile Only: Top Row and Collapsible Filters */}
                    <div className="d-md-none">
                        <div className="d-flex flex-row justify-content-between align-items-stretch gap-2 mb-4">
                            <div
                                className="refresh-container d-flex align-items-center justify-content-center flex-grow-1"
                                style={{
                                    background: darkMode ? '#18213a' : '#f8fafc',
                                    color: darkMode ? '#e0e6f0' : '#475569',
                                    borderRadius: '12px',
                                    padding: '10px 12px',
                                    fontSize: '0.8rem',
                                    fontWeight: 500,
                                    border: darkMode ? '1px solid rgba(44, 62, 80, 0.6)' : '1px solid rgba(108, 117, 125, 0.1)',
                                    boxShadow: '0 2px 4px 0 rgba(0,0,0,0.02)',
                                    margin: 0,
                                    whiteSpace: 'nowrap',
                                    overflow: 'hidden',
                                    textOverflow: 'ellipsis'
                                }}
                            >
                                {loading ? (
                                    <span>{polyglot.t('label.loading')}</span>
                                ) : (
                                    <span style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>{lastUpdated || ''}</span>
                                )}
                            </div>

                            <button
                                onClick={() => {
                                    setShowFilters((prev) => {
                                        const next = !prev;
                                        saveShowFilters(next);
                                        return next;
                                    });
                                }}
                                style={{
                                    background: darkMode ? (showFilters ? '#253250' : '#18213a') : (showFilters ? '#e2e8f0' : '#f8fafc'),
                                    color: darkMode ? '#e0e6f0' : '#475569',
                                    border: darkMode ? '1px solid rgba(44, 62, 80, 0.6)' : '1px solid rgba(108, 117, 125, 0.1)',
                                    borderRadius: '12px',
                                    padding: '10px 16px',
                                    fontWeight: 600,
                                    fontSize: '0.85rem',
                                    cursor: 'pointer',
                                    transition: 'all 0.2s ease',
                                    margin: 0,
                                    whiteSpace: 'nowrap',
                                    flexShrink: 0
                                }}
                                aria-expanded={showFilters}
                                aria-controls="signal-filters-container"
                            >
                                {showFilters
                                    ? polyglot.t('filters.hide')
                                    : polyglot.t('filters.show') + (filterCount > 0 ? ` (${filterCount})` : '')}
                            </button>
                        </div>

                        {showFilters && (
                            <div id="signal-filters-container" style={{
                                background: darkMode ? '#141c2f' : '#f1f5f9',
                                borderRadius: '16px',
                                padding: '16px',
                                marginBottom: '16px',
                                border: darkMode ? '1px solid rgba(44, 62, 80, 0.4)' : '1px solid rgba(108, 117, 125, 0.05)'
                            }}>
                                <SignalFilters
                                    filters={filters}
                                    onChange={setFilters}
                                    polyglot={polyglot}
                                    darkMode={darkMode}
                                    availableMarkets={['USD_M_FUTURES', 'SPOT']}
                                    availableSignals={['buy', 'sell']}
                                    availableReasons={['spike', 'reversal', 'trend']}
                                    onCountChange={setFilterCount}
                                />
                            </div>
                        )}
                    </div>

                    <SignalData
                        refreshSignal={refreshSignal}
                        onDataLoaded={handleDataLoaded}
                        triggerRefresh={triggerRefresh}
                        polyglot={polyglot}
                        filters={filters}
                        hideActionsOnDesktop={true}
                    />
                </main>
            </div>

            {SessionExpiredModal}
        </Container>
    );
};

export default MainPage;
